     private fun changeRate(delta: Float) {
         val cur = prefs.getFloat("rate", 1.0f)
         val r = Rates.step(cur, delta)
         prefs.edit().putFloat("rate", r).apply()
         try { tts?.setSpeechRate(r) } catch (e: Exception) { }
         speedPctText?.text = Rates.percent(r).toString() + "%"
         rebuildPanel()
     }

     private fun cycleReadOrder() {
         val next = ReadingOrder.next(readOrderMode())
         prefs.edit().putString("read_order", next).apply()
         // Пересортируем блоки последнего распознавания новым направлением.
         if (layoutBlocks.isNotEmpty()) {
             layoutBlocks = ReadingOrder.order(layoutBlocks, next)
             activeBlock = -1
             refreshFrame()
         }
         Toast.makeText(this, "Чтение: ${ReadingOrder.label(next)}", Toast.LENGTH_SHORT).show()
         rebuildPanel()
     }

     // ------------------------------------------------------------------
     // Режимы чтения и список приложений
     // ------------------------------------------------------------------

     private fun readMode(): String = ReadMode.normalize(prefs.getString("read_mode", ReadMode.DEFAULT))

     /** Переключить режим и применить его к порядку блоков, переводу и рамке. */
     private fun cycleReadMode() {
         val next = ReadMode.next(readMode())
         prefs.edit().putString("read_mode", next).apply()
         val order = ReadMode.order(next)
         val tr = ReadMode.translate(next)
         val tdir = ReadMode.translateDir(next)
         prefs.edit().apply {
             putString("read_order", order)
             if (tr != null) putBoolean("translate", tr)
             if (tdir != null) putString("translate_dir", tdir)
         }.apply()
         // Рамку ставим только если это имеет смысл для режима (манга/комикс —
         // весь экран, субтитры — низ).
         val preset = ReadMode.regionPreset(next)
         if (preset != regionPreset()) {
             val box = Region.rectFor(preset, screenSize().x, screenSize().y)
             setPreset(preset, box)
         }
         if (layoutBlocks.isNotEmpty()) {
             layoutBlocks = ReadingOrder.order(layoutBlocks, order)
             activeBlock = -1
             refreshFrame()
         }
         Toast.makeText(this, "Режим: ${ReadMode.label(next)}", Toast.LENGTH_SHORT).show()
         rebuildPanel()
     }

