     private fun ensureTts() {
         if (tts != null) return
         try {
             tts = TextToSpeech(applicationContext) { status ->
                 ttsReady = (status == TextToSpeech.SUCCESS)
                 val t = tts ?: return@TextToSpeech
                 try { t.setSpeechRate(prefs.getFloat("rate", 1.0f)) } catch (e: Exception) { }
                 t.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
                     override fun onStart(utteranceId: String?) {
                         setSpeaking(true)
                     }
                     @Deprecated("dep")
                     override fun onError(utteranceId: String?) { onDone(utteranceId) }
                     override fun onError(utteranceId: String?, errorCode: Int) {
                         onDone(utteranceId)
                     }
                     override fun onStop(utteranceId: String?, interrupted: Boolean) {
                         onDone(utteranceId)
                     }
                     override fun onDone(utteranceId: String?) {
                         ui.post {
                             setSpeaking(false)
                             if (autoReading) {
                                 ui.postDelayed({ if (autoReading) advanceOrWait() }, 350)
                             }
                         }
                     }
                 })
             }
         } catch (e: Exception) {
             tts = null
             ttsReady = false
         }
     }

     /** Применяет сохранённый голос (по имени из выбора), если задан. */
     private fun applyVoicePref(t: TextToSpeech) {
         val name = prefs.getString("voice_name", "") ?: ""
         if (name.isBlank()) return
         try {
             val v = t.voices?.firstOrNull { it.name == name } ?: return
             t.voice = v
         } catch (e: Exception) { }
     }

     private fun currentVoiceLabel(): String {
         val name = prefs.getString("voice_name", "") ?: ""
         if (name.startsWith("edge:")) return name.removePrefix("edge:").take(26) + " · Edge"
         if (name.isBlank()) return (if (ttsBackend() == "edge") edgeVoiceName().take(22) + " · Edge" else "голос системы")
         return name.replace("language", "").trim('-', ' ').take(26)
     }

     /** Окно выбора голоса: список установленных TTS-голосов, тап = выбрать и прослушать. */
     private var voiceWin: View? = null

     private fun openVoicePicker() {
         if (voiceWin != null) return
         closeMiniPanel()
         ensureTts()
         val card = LinearLayout(this).apply {
             orientation = LinearLayout.VERTICAL
             background = rounded(cardBg, 18f)
             setPadding(dp(10), dp(10), dp(10), dp(10))
         }
         val sp = screenSize()
         val cw = minOf(dp(360), sp.x - dp(24))
         val ch = minOf(dp(440), sp.y - dp(140))
         val scroll = android.widget.ScrollView(this)
         val list = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
         val pad = dp(6)
         list.setPadding(pad, pad, pad, pad)
         scroll.addView(list)
         card.addView(scroll, LinearLayout.LayoutParams(cw, ch))

         fun fill() {
             list.removeAllViews()
             val t = tts
             val voices = try { t?.voices?.sortedBy { it.name } } catch (e: Exception) { null }
             val head = TextView(this).apply {
                 text = "Выбор голоса (тап = выбрать и прослушать)"
                 textSize = 15f
                 setTextColor(txtTitle)
                 setPadding(dp(4), dp(4), dp(4), dp(10))
             }
             list.addView(head)
             run {
                 val hdr = TextView(this).apply {
                     text = "Голоса Edge (онлайн, как в браузере):"
                     textSize = 13f
                     setTextColor(txtSub)
                     setPadding(dp(4), dp(4), dp(4), dp(6))
                 }
                 list.addView(hdr)
             }
             run {
                 var edge = EdgeTts.cachedVoices(this@OverlayService)
                 if (edge.isEmpty()) {
                     edge = listOf(
                         EdgeTts.EdgeVoice("ru-RU-SvetlanaNeural", "Female", "ru-RU", "Светлана"),
                         EdgeTts.EdgeVoice("ru-RU-DmitryNeural", "Male", "ru-RU", "Дмитрий"),
                         EdgeTts.EdgeVoice("ru-RU-DariyaNeural", "Female", "ru-RU", "Дарья"),
                     )
                 }
                 val cur = prefs.getString("voice_name", "")
                 for (v in edge.filter { it.locale.startsWith("ru-", true) || it.multilingual }.take(24)) {
                     val key = "edge:" + v.shortName
                     val row = TextView(this).apply {
                         text = (if (cur == key) "✅ " else "") + v.label
                         textSize = 13f
                         setTextColor(if (cur == key) btnBgAccent else txtTitle)
                         setPadding(dp(8), dp(10), dp(8), dp(10))
                         background = rounded(Color.parseColor("#2E323E"), 10f)
                     }
                     val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
                     lp.setMargins(0, 0, 0, dp(6))
                     row.layoutParams = lp
                     row.setOnClickListener {
                         prefs.edit()
                             .putString("voice_name", key)
                             .putString("edge_voice", v.shortName)
                             .putString("tts_backend", "edge")
                             .apply()
                         closeVoicePicker()
                         speakNowSilentPreview("Привет! Это мой голос. Желаю приятного чтения.")
                     }
                     list.addView(row)
                 }
             }
             run {
                 val hdr2 = TextView(this).apply {
                     text = "Системные голоса телефона:"
                     textSize = 13f
                     setTextColor(txtSub)
                     setPadding(dp(4), dp(10), dp(4), dp(6))
                 }
                 list.addView(hdr2)
             }
             if (voices.isNullOrEmpty()) {
                 val m = TextView(this).apply {
                     text = "TTS ещё не готов или голосов нет. Откройте системные настройки TTS (⚙) и загрузите русские голоса."
                     textSize = 13f
                     setTextColor(txtSub)
                     setPadding(dp(4), dp(6), dp(4), dp(6))
                 }
                 list.addView(m)
             } else {
                 val cur = prefs.getString("voice_name", "")
                 for (v in voices) {
                     val net = try { v.isNetworkConnectionRequired } catch (e: Exception) { false }
                     val row = TextView(this).apply {
                         text = (if (v.name == cur) "✅ " else "") + v.name + "\n" +
                             v.locale.displayName + (if (net) " · сетевой" else " · локальный")
                         textSize = 13f
                         setTextColor(if (v.name == cur) btnBgAccent else txtTitle)
                         setPadding(dp(8), dp(10), dp(8), dp(10))
                         background = rounded(Color.parseColor("#2E323E"), 10f)
                     }
                     val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
                     lp.setMargins(0, 0, 0, dp(6))
                     row.layoutParams = lp
                     row.setOnClickListener {
                         prefs.edit()
                             .putString("voice_name", v.name)
                             .putString("tts_backend", "system")
                             .apply()
                         try { t?.voice = v } catch (e: Exception) { }
                         closeVoicePicker()
                         // проба: сразу озвучиваем короткую фразу выбранным голосом
                         speakNowSilentPreview("Привет! Это мой голос. Желаю приятного чтения.")
                     }
                     list.addView(row)
                 }
             }
         }
         fill()
         Thread {
             try {
                 val fresh = runBlocking { EdgeTts.fetchVoices() }
                 if (fresh.isNotEmpty()) {
                     EdgeTts.cacheVoices(this@OverlayService, fresh)
                     ui.post { if (voiceWin != null) fill() }
                 }
             } catch (e: Exception) {
                 android.util.Log.d("Edge", "fetchVoices: ${e.message}")
             }
         }.start()
         if (voicesNoneYet(list)) {
             // TTS асинхронный: перечитать список через секунду
             ui.postDelayed({ if (voiceWin != null) fill() }, 900)
         }

         // «✕ Закрыть» вместо клика по затемнению — карточка не закрывает экран.
         card.addView(TextView(this).apply {
             text = "✕ Закрыть"
             textSize = 13f
             setTextColor(txtSub)
             gravity = Gravity.CENTER
             setPadding(0, dp(8), 0, 0)
             setOnClickListener { closeVoicePicker() }
         })

         // Компактное окно рядом с пузырём, без перекрытия всего экрана.
         val lp = overlayLp(WindowManager.LayoutParams.WRAP_CONTENT, WindowManager.LayoutParams.WRAP_CONTENT, true)
         val base = mainLp
         lp.x = (((base?.x ?: (sp.x - dp(76))) - cw - dp(8)).coerceIn(0, (sp.x - cw).coerceAtLeast(0)))
         lp.y = ((base?.y ?: (sp.y * 0.42f).toInt()) + dp(20)).coerceIn(0, (sp.y - ch - dp(80)).coerceAtLeast(0))
         try { wm.addView(card, lp) } catch (e: Exception) { }
         voiceWin = card
         rebuildPanel()
     }

     private fun voicesNoneYet(list: LinearLayout): Boolean {
         val t = tts ?: return true
         return try { !ttsReady || t.voices.isNullOrEmpty() } catch (e: Exception) { true }
     }

     private fun closeVoicePicker() {
         try { voiceWin?.let { wm.removeView(it) } } catch (e: Exception) { }
         voiceWin = null
         rebuildPanel()
     }

     /** Пробная фраза: без пометки «идёт чтение» — просто прослушать голос. */
     private fun speakNowSilentPreview(phrase: String) {
         if (ttsBackend() == "edge") {
             speakEdge(phrase)
             return
         }
         val t = tts
         if (t == null || !ttsReady) {
             ui.postDelayed({ speakNowSilentPreview(phrase) }, 600)
             return
         }
         try {
             t.language = pickLocale(phrase)
             applyVoicePref(t)
             t.setSpeechRate(prefs.getFloat("rate", 1.0f))
             t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
             t.speak(phrase, TextToSpeech.QUEUE_FLUSH, android.os.Bundle(), "ovr-preview")
         } catch (e: Exception) { }
     }

     private fun ttsBackend(): String = prefs.getString("tts_backend", "edge") ?: "edge"

     /** Edge-голос: явный выбор из списка, иначе по тембру ♀/♂. */
     private fun edgeVoiceName(): String {
         val custom = prefs.getString("edge_voice", "") ?: ""
         if (custom.isNotBlank()) return custom
         return if (prefs.getString("gender", "female") == "male") "ru-RU-DmitryNeural" else "ru-RU-SvetlanaNeural"
     }

     private fun pickLocale(text: String): Locale {
         var cyr = 0
         var lat = 0
         for (ch in text) {
             if (ch in 'А'..'я' || ch == 'Ё' || ch == 'ё') cyr++
             else if (ch in 'A'..'Z' || ch in 'a'..'z') lat++
         }
         return if (cyr >= lat) Locale("ru", "RU") else Locale.ENGLISH
     }

     private fun speak(text: String) {
         if (text.isBlank()) return
         ensureTts()
         val t = tts
         if (t == null || !ttsReady) {
             // Системный TTS инициализируется асинхронно: без ожидания реплика
             // терялась молча (speak до onInit не проигрывается).
             ui.postDelayed({ speakNow(text) }, 650)
             return
         }
         speakNow(text)
     }

     private fun speakNow(text: String) {
         startSpeakClock(text)
         if (ttsBackend() == "edge") {
             speakEdge(text)
             return
         }
         speakNowSystem(text)
     }

     private fun speakNowSystem(text: String) {
         val t = tts
         if (t == null || !ttsReady) {
             // не готов — вернёмся через speak(), он повторит
             ui.postDelayed({ speak(text) }, 650)
             return
         }
         try {
             t.language = pickLocale(text)
             applyVoicePref(t)
             t.setSpeechRate(prefs.getFloat("rate", 1.0f))
             t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
             setSpeaking(true)
             val params = android.os.Bundle()
             t.speak(text, TextToSpeech.QUEUE_FLUSH, params, "ovr-utterance")
         } catch (e: Exception) {
             setSpeaking(false)
         }
     }

     /** Часы прогресса озвучивания: подсветка блока i по мере чтения текста. */
     private fun startSpeakClock(text: String) {
         ui.removeCallbacks(speakTick)
         val n = layoutBlocks.size
         if (n <= 0) {
             activeBlock = -1
             refreshFrame()
             return
         }
         val rate = prefs.getFloat("rate", 1.0f).coerceAtLeast(0.25f)
         speakTotalMs = ((text.length * 1000.0f) / (16.0f * rate)).coerceAtLeast(1500f)
         speakStartMs = SystemClock.elapsedRealtime()
         activeBlock = 0
         refreshFrame()
         ui.postDelayed(speakTick, 400L)
     }

     private fun tickSpeak() {
         if (layoutBlocks.isEmpty() || !speaking) {
             stopSpeakClock()
             return
         }
         val f = (SystemClock.elapsedRealtime() - speakStartMs).toFloat() / speakTotalMs
         val n = layoutBlocks.size
         val idx = (f * n).toInt().coerceIn(0, n - 1)
         if (idx != activeBlock) {
             activeBlock = idx
             refreshFrame()
         }
         if (f < 1f) ui.postDelayed(speakTick, 400L) else stopSpeakClock()
     }

     private fun stopSpeakClock() {
         ui.removeCallbacks(speakTick)
     }

     /** Облачка едут вместе с контентом при прокрутке, чтобы было видно конец скана. */
     private fun animateBoxes(deltaY: Int) {
         ui.removeCallbacks(boxAnim)
         boxAnimFrom = boxShiftY
         boxAnimTo = boxShiftY + deltaY
         boxAnimStart = SystemClock.elapsedRealtime()
         ui.post(boxAnim)
     }

     private fun tickBoxAnim() {
         val f = ((SystemClock.elapsedRealtime() - boxAnimStart) / 800f).coerceIn(0f, 1f)
         boxShiftY = boxAnimFrom + (boxAnimTo - boxAnimFrom) * f
         frameView?.invalidate()
         if (f < 1f) ui.postDelayed(boxAnim, 16L)
     }

     private fun stopBoxAnim() {
         ui.removeCallbacks(boxAnim)
         boxShiftY = 0f
     }

     /** Синтез сетевым голосом Edge: тексты уходят в Microsoft, кадры — никогда. */
     private fun speakEdge(text: String) {
         setSpeaking(true)
         val voice = edgeVoiceName()
         val rate = prefs.getFloat("rate", 1.0f)
         val pitch = if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f
         val gen = speakGen // стоп/onDestroy между синтезом и игрой — отменит проигрывание
         Thread {
             var ok = false
             try {
                 val ratePercent = ((rate - 1f) * 100f).roundToInt()
                 val pitchHz = ((pitch - 1f) * 200f).roundToInt()
                 val file = runBlocking {
                     EdgeTts.synthesizeToFile(applicationContext, text, voice, ratePercent, pitchHz)
                 }
                 if (file != null) {
                     ok = true
                     ui.post { playEdgeAudio(file, gen) }
                 }
             } catch (e: Exception) {
                 android.util.Log.w("Edge", "speakEdge: ${e.message}")
             }
             if (!ok) {
                 // нет сети/сервер недоступен → фолбэк на системный TTS
                 ui.post { speakNowSystem(text) }
             }
         }.start()
     }

     private fun playEdgeAudio(file: java.io.File, gen: Long) {
         if (gen != speakGen) {
             // чтение остановили, пока шёл синтез — файл не нужен
             runCatching { file.delete() }
             setSpeaking(false)
             return
         }
         try {
             runCatching { mediaPlayer?.release() }
             val mp = MediaPlayer()
             mediaPlayer = mp
             mp.setAudioAttributes(
                 AudioAttributes.Builder()
                     .setUsage(AudioAttributes.USAGE_MEDIA)
                     .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                     .build(),
             )
             mp.setDataSource(file.absolutePath)
             mp.setOnErrorListener { _, _, _ ->
                 runCatching { file.delete() }
                 runCatching { mp.release() }
                 mediaPlayer = null
                 setSpeaking(false)
                 true
             }
             mp.setOnPreparedListener { media ->
                 media.start()
             }
             mp.setOnCompletionListener { done ->
                 runCatching { done.release() }
                 mediaPlayer = null
                 runCatching { file.delete() }
                 setSpeaking(false)
                 if (autoReading) {
                     ui.postDelayed({ if (autoReading) advanceOrWait() }, 350)
                 }
             }
             mp.prepareAsync()
         } catch (e: Exception) {
             android.util.Log.w("Edge", "playback: ${e.message}")
             runCatching { file.delete() }
             setSpeaking(false)
         }
     }

     // ------------------------------------------------------------------
     // Сценарии чтения
     // ------------------------------------------------------------------

     private fun scanOnce() {
         preview = "Сканирую…"
         previewText?.text = preview
         notifyStatus("Сканирую рамку…")
         scanningFrame = true
         refreshFrame()
         ocrScan { text ->
             scanningFrame = false
             refreshFrame()
             if (text.isBlank()) {
                 if (!preview.startsWith("⚠")) preview = "Текст не найден в рамке"
                 previewText?.text = preview
                 notifyStatus(preview)
                 return@ocrScan
             }
             preview = text
             previewText?.text = preview
             notifyStatus(text) // распознанное текстом видно в шторке
             speak(text)
         }
     }

     private fun startAutoRead() {
         if (autoReading) return
         autoReading = true
         lastText = ""
         repeatCount = 0
         tapStreak = 0
         scanThrottle.reset()
         tapThrottle.reset()
         notifThrottle.reset()
         readBuffer.setLength(0)
         rebuildPanel()
         showStopButton()
         refreshFrame()
         try {
             val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
             @Suppress("DEPRECATION")
             wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "ovr:read")
             wakeLock?.acquire(30 * 60 * 1000L)
         } catch (e: Exception) { }
         autoStep()
     }

     fun stopAutoRead() {
         autoReading = false
         tapStreak = 0
         hideStopButton()
         speakGen++ // прерываем и запрещаем доигрывать уже синтезированное
         try { tts?.stop() } catch (e: Exception) { }
         runCatching { mediaPlayer?.let { if (it.isPlaying) it.stop(); it.release() } }
         mediaPlayer = null
         setSpeaking(false)
         scanningFrame = false
         stopSpeakClock()
         stopBoxAnim()
         layoutBlocks = emptyList()
         activeBlock = -1
         rebuildPanel()
         refreshFrame()
         notifyStatus(if (preview.isNotBlank()) preview else null)
     }

     /** Столько раз подряд разрешаем «пустой/тот же текст» перед авто-стопом. */
     private val maxRepeats = 6

     /** Остановить только озвучку (авточтение при этом не трогаем). */
     private fun stopVoice() {
         speakGen++
         try { tts?.stop() } catch (e: Exception) { }
         runCatching { mediaPlayer?.let { if (it.isPlaying) it.stop(); it.release() } }
         mediaPlayer = null
         setSpeaking(false)
         stopSpeakClock()
         activeBlock = -1
         hideStopButton()
         refreshFrame()
         if (expanded) rebuildPanel()
     }

     private fun autoStep() {
         if (!autoReading) return
         scanningFrame = true
         refreshFrame()
         ocrScan { text ->
             if (!autoReading) return@ocrScan
             scanningFrame = false
             refreshFrame()
             val norm = norm(text)
             if (norm.isBlank() || norm == lastText) {
                 // «Лайв» и «Субтитры игр» не листают: читаем один экран и ждём,
                 // пока пользователь сам пролистает.
                 if (!ReadMode.autoScroll(readMode())) {
                     stopAutoRead()
                     preview = "ℹ Режим «${ReadMode.label(readMode())}»: листайте страницу вручную — оверлей прочитает новый экран"
                     previewText?.text = preview
                     notifyStatus(preview)
                     return@ocrScan
                 }
                 repeatCount++
                 if (repeatCount >= maxRepeats) {
                     // Страница не меняется: конец текста или выключена
                     // прокрутка. Раньше цикл крутился вечно.
                     stopAutoRead()
                     preview = "⚠ Авточтение остановлено: текст в рамке не меняется"
                     previewText?.text = preview
                     notifyStatus(preview)
                     return@ocrScan
                 }
                 // В автосубтитрах экран не изменился — значит новелла ждёт нажатия.
                 if (ReadMode.autoTap(readMode())) advanceOrWait() else scrollAndContinue()
                 return@ocrScan
             }
             repeatCount = 0
             tapStreak = 0
             lastText = norm
             appendRead(text)
             notifyStatus(text)
             speak(text)
             // продолжение — из onDone говорилки
         }
     }

     /**
      * Автосубтитры: после озвучки решаем — листать сюжет тапом или ждать.
      * На экране выбора реплик не тапаем: выбор сбросится не туда.
      */
     private fun advanceOrWait() {
         if (!autoReading) return
         if (!ReadMode.autoTap(readMode())) {
             scrollAndContinue()
             return
         }
         val blocks = layoutBlocks
         val decision = AutoPilot.decision(
             blocks.map { AutoPilot.Block(it.width(), it.height()) },
             screenSize().y,
         )
         val svc = ScrollAccessibilityService.instance
         if (decision == AutoPilot.WAIT) {
             // Выбор реплик: ждём, пока игрок выберет сам.
             preview = "🎬 Выбор реплик — жду решения игрока"
             previewText?.text = preview
             ui.postDelayed({ if (autoReading) autoStep() }, 2500)
             return
         }
         if (svc == null) {
             preview = "⚠ Автопрокрутка выключена — включите службу, иначе «дальше» не нажмётся"
             previewText?.text = preview
             ui.postDelayed({ if (autoReading) autoStep() }, 2500)
             return
         }
         // Тапаем в самый нижний блок текста — там обычно «дальше»/продолжение.
         if (tapStreak >= MAX_TAP_STREAK) {
             // Зацикливание: нажимаем, а экран тот же. Останавливаемся, чтобы не
             // долбить по экрану и не грузить систему.
             stopAutoRead()
             preview = "⚠ Автосубтитры остановлены: ${MAX_TAP_STREAK} нажатий подряд без нового текста"
             previewText?.text = preview
             notifyStatus(preview)
             return
         }
         val tgap = tapThrottle.remaining(SystemClock.elapsedRealtime())
         if (tgap > 0) {
             ui.postDelayed({ if (autoReading) autoStep() }, tgap)
             return
         }
         tapThrottle.allow(SystemClock.elapsedRealtime())
         tapStreak++
         val r = ocrRect()
         val target = blocks.maxByOrNull { it.bottom } ?: blocks.firstOrNull()
         val tx = target?.let { (it.left + it.right) / 2 } ?: (r.left + r.right) / 2
         val ty = target?.let { (it.bottom + r.bottom) / 2 } ?: (r.top + r.bottom) / 2
         try { svc.tap(tx, ty.coerceIn(r.top, r.bottom)) } catch (e: Exception) { }
         ui.postDelayed({ if (autoReading) autoStep() }, 1500)
     }

     private fun scrollAndContinue() {
         val r = ocrRect()
         val svc = ScrollAccessibilityService.instance
         if (svc != null) {
             // Прокрутка двигает контент вверх: облачка едут вместе с ним, пока
             // не подоспеет новый скан — так видно, где заканчивается прочитанное.
             val h = (r.bottom - r.top).coerceAtLeast(1)
             animateBoxes(-(h * 0.22f).toInt())
             try { svc.swipeForward(r.left, r.top, r.right, r.bottom) } catch (e: Exception) { }
             ui.postDelayed({ if (autoReading) autoStep() }, 1500)
         } else {
             // Автопрокрутка выключена: ждём и читаем то же место снова (так видно,
             // что службу спецвозможностей нужно включить — есть подсказка в меню).
             ui.postDelayed({
                 if (!autoReading) return@postDelayed
                 preview = "⚠ Автопрокрутка выключена — включите «Yomikai Оверлей — прокрутка» в спец. возможностях"
                 previewText?.text = preview
                 lastText = "" // пусть перечитает после включения/ручной прокрутки
                 ui.postDelayed({ if (autoReading) autoStep() }, 2500)
             }, 600)
         }
     }

-    private fun norm(s: String) = s.lowercase().replace("\\s+".toRegex(), " ").trim()
+    private fun norm(s: String) = s.lowercase().replace(wsRe, " ").trim()

     override fun onConfigurationChanged(newConfig: Configuration) {
         super.onConfigurationChanged(newConfig)
         refreshFrame()
         // После поворота пузырь мог оказаться за пределами нового экрана.
         val lp = mainLp ?: return
         val s = screenSize()
         val vw = mainRoot?.width?.takeIf { it > 0 } ?: dp(56)
         val vh = mainRoot?.height?.takeIf { it > 0 } ?: dp(56)
         val nx = clamp(lp.x, 0, (s.x - vw).coerceAtLeast(0))
         val ny = clamp(lp.y, 0, (s.y - vh).coerceAtLeast(0))
         if (nx != lp.x || ny != lp.y) {
             lp.x = nx
             lp.y = ny
             try { wm.updateViewLayout(mainRoot, lp) } catch (e: Exception) { }
         }
         placeStopButton()
     }
 }

