fun postChatFull(endpoint: String, bearer: String?, body: JSONObject): ChatResult? {
        return runCatching {
            val c = URL(endpoint).openConnection() as HttpURLConnection
            c.requestMethod = "POST"
            c.doOutput = true
            c.connectTimeout = 15_000
            c.readTimeout = 35_000
            c.setRequestProperty("Content-Type", "application/json")
            c.setRequestProperty("HTTP-Referer", "https://github.com/sj0404-collab/overlay-translator")
            c.setRequestProperty("X-Title", "OverlayTranslator")
            if (!bearer.isNullOrBlank()) c.setRequestProperty("Authorization", bearer)
            val raw = try {
                c.outputStream.use { it.write(body.toString().toByteArray()) }
                val stream = if (c.responseCode in 200..299) c.inputStream else c.errorStream
                // Раньше читалось без ограничения и без use{}: на 4xx/5xx
                // getInputStream() бросает исключение, disconnect() не
                // доходил, и сокет навсегда оставался в keep-alive пуле.
                stream?.use { String(it.readNBytes(MAX_RESPONSE_BYTES), Charsets.UTF_8) }.orEmpty()
            } finally {
                c.disconnect()
            }
            if (raw.isBlank()) return@runCatching null
            val json = runCatching { JSONObject(raw) }.getOrNull() ?: return@runCatching null

            // OpenAI-совместимый формат.
            val choices = json.optJSONArray("choices")
            if (choices != null && choices.length() > 0) {
                val msg = choices.optJSONObject(0)
                    ?.optJSONObject("message")
                    ?.optString("content")
                val usage = json.optJSONObject("usage")
                val tokens = usage?.optLong("total_tokens", 0L) ?: 0L
                if (!msg.isNullOrBlank()) {
                    return@runCatching ChatResult(RuText.stripWrappers(msg), tokens)
                }
            }

            // Формат Gemini.
            val cands = json.optJSONArray("candidates")
            if (cands != null && cands.length() > 0) {
                val txt = cands.optJSONObject(0)
                    ?.optJSONObject("content")
                    ?.optJSONArray("parts")
                    ?.optJSONObject(0)
                    ?.optString("text")
                val tokens = json.optJSONObject("usageMetadata")
                    ?.optLong("totalTokenCount", 0L) ?: 0L
                if (!txt.isNullOrBlank()) {
                    return@runCatching ChatResult(RuText.stripWrappers(txt), tokens)
                }
            }
            null
        }.getOrNull()
    }

