/** Перерисовать список приложений по поисковой строке. */
    private fun fillAppList(query: String?) {
        val box = appListBox ?: return
        val gen = ++appListGen
        box.removeAllViews()
        box.addView(TextView(this).apply {
            text = "Загрузка списка приложений…"
            textSize = 13f
            setTextColor(txtSub)
            setPadding(dp(6), dp(12), dp(6), dp(12))
        })
        val ctx = applicationContext
        Thread {
            // Список пакетов (~300) и иконки (по одному binder-вызову на
            // приложение) — это сотни IPC в UI-потоке, т.е. ANR. Раньше всё
            // это выполнялось синхронно на каждый символ поисковой строки.
            if (!running) return@Thread
            val apps = try { AppCatalog.filter(AppCatalog.load(ctx), query) } catch (e: Exception) { emptyList() }
            if (!running) return@Thread
            val shown = apps.take(60)
            val icons = HashMap<String, android.graphics.drawable.Drawable?>(shown.size)
            for (a in shown) {
                if (!running) return@Thread
                icons[a.pkg] = AppCatalog.icon(ctx, a)
            }
            ui.post {
                // Пока грузились, пользователь мог напечатать ещё символ или
                // закрыть панель — такой результат больше неактуален.
                if (gen != appListGen || appListBox == null) return@post
                renderAppList(apps, shown, icons)
            }
        }.start()
    }

    private fun renderAppList(
        apps: List<AppCatalog.App>,
        shown: List<AppCatalog.App>,
        icons: Map<String, android.graphics.drawable.Drawable?>,
    ) {
        val box = appListBox ?: return
        box.removeAllViews()
        if (apps.isEmpty()) {
            box.addView(TextView(this).apply {
                text = "Ничего не найдено"
                textSize = 13f
                setTextColor(txtSub)
                setPadding(dp(6), dp(12), dp(6), dp(12))
            })
            return
        }
        for (a in shown) {
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(dp(6), dp(8), dp(6), dp(8))
                setOnClickListener {
                    closeAppPanel()
                    AppCatalog.launch(this@OverlayService, a)
                }
            }
            val icon = icons[a.pkg]
            if (icon != null) {
                row.addView(ImageView(this).apply {
                    setImageDrawable(icon)
                    layoutParams = LinearLayout.LayoutParams(dp(34), dp(34)).apply {
                        rightMargin = dp(10)
                    }
                })
            } else {
                row.addView(View(this).apply {
                    layoutParams = LinearLayout.LayoutParams(dp(34), dp(34)).apply { rightMargin = dp(10) }
                })
            }
            row.addView(LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                addView(TextView(this@OverlayService).apply {
                    text = a.label
                    textSize = 14f
                    setTextColor(txtTitle)
                    maxLines = 1
                })
                addView(TextView(this@OverlayService).apply {
                    text = a.pkg
                    textSize = 10f
                    setTextColor(txtSub)
                    maxLines = 1
                })
            })
            box.addView(row)
        }
        if (apps.size > shown.size) {
            box.addView(TextView(this).apply {
                text = "…и ещё ${apps.size - shown.size}. Уточните поиск."
                textSize = 11f
                setTextColor(txtSub)
                setPadding(dp(6), dp(8), dp(6), 0)
            })
        }
    }

    private fun closeAppPanel() {
        try { appWin?.let { wm.removeView(it) } } catch (e: Exception) { }
        appWin = null
        appLp = null
        appListBox = null
        appListGen++ // отменить запоздалый рендер из фонового потока
    }

