input.newString:
/** Диалог со списком приложений устройства: поиск и запуск в один тап. */
    private fun showApps() {
        // AppCatalog.load() и AppCatalog.icon() — тяжёлые вызовы: список ~300
        // пакетов плюс по одному binder-вызову на ярлык и на иконку. Раньше всё
        // это выполнялось на UI-потоке (до показа диалога и на каждый символ
        // поиска) — прямой путь к ANR. Теперь фон готовит данные, UI только
        // собирает вьюхи.
        val ctx = applicationContext
        val executor = Executors.newSingleThreadExecutor()
        val main = Handler(Looper.getMainLooper())
        val iconCache = HashMap<String, android.graphics.drawable.Drawable?>()

        var all: List<AppCatalog.App> = emptyList()
        var loaded = false
        var generation = 0

        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(8))
        }
        root.setBackgroundColor(Color.parseColor("#14161B"))

        val search = android.widget.EditText(this).apply {
            hint = "Поиск приложения…"
            setTextColor(Color.parseColor("#EEEFF3"))
            setHintTextColor(Color.parseColor("#7784A0"))
            textSize = 14f
            isSingleLine = true
            setBackgroundColor(Color.parseColor("#1E2129"))
            setPadding(dp(12), 0, dp(12), 0)
        }
        root.addView(search, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(48)))

        val listBox = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(0, dp(8), 0, 0)
        }
        root.addView(
            ScrollView(this).apply { addView(listBox) },
            LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 0, 1f)
        )

        val dlg = android.app.AlertDialog.Builder(this)
            .setView(root)
            .setNegativeButton("Закрыть") { _, _ -> executor.shutdown() }
            .create()

        fun showStatus(text: String) {
            listBox.removeAllViews()
            listBox.addView(TextView(this).apply {
                this.text = text
                textSize = 14f
                setTextColor(Color.parseColor("#7784A0"))
                setPadding(dp(4), dp(12), 0, dp(12))
            })
        }

        fun render(rows: List<Pair<AppCatalog.App, android.graphics.drawable.Drawable?>>) {
            listBox.removeAllViews()
            if (rows.isEmpty()) {
                showStatus("Ничего не найдено")
                return
            }
            for ((a, ic) in rows) {
                val row = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    setPadding(dp(6), dp(10), dp(6), dp(10))
                    setOnClickListener {
                        try { dlg.dismiss() } catch (e: Exception) { }
                        executor.shutdown()
                        if (!AppCatalog.launch(this@MainActivity, a)) {
                            Toast.makeText(this@MainActivity, "Не удалось открыть", Toast.LENGTH_SHORT).show()
                        }
                    }
                }
                if (ic != null) {
                    row.addView(android.widget.ImageView(this).apply {
                        setImageDrawable(ic)
                        layoutParams = LinearLayout.LayoutParams(dp(36), dp(36)).apply { rightMargin = dp(12) }
                    })
                }
                row.addView(LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    addView(TextView(this@MainActivity).apply {
                        text = a.label
                        textSize = 15f
                        setTextColor(Color.parseColor("#EEEFF3"))
                        maxLines = 1
                    })
                    addView(TextView(this@MainActivity).apply {
                        text = a.pkg
                        textSize = 11f
                        setTextColor(Color.parseColor("#7784A0"))
                        maxLines = 1
                    })
                })
                listBox.addView(row)
            }
        }

        /** Фон: фильтр + иконки. UI получает уже готовые строки. */
        fun refresh(query: String?) {
            val gen = ++generation
            executor.execute {
                if (executor.isShutdown) return@execute
                val rows = if (!loaded) {
                    emptyList()
                } else {
                    AppCatalog.filter(all, query).take(80).map { a ->
                        val ic = if (iconCache.containsKey(a.pkg)) iconCache[a.pkg]
                        else AppCatalog.icon(ctx, a).also { iconCache[a.pkg] = it }
                        a to ic
                    }
                }
                main.post {
                    if (gen != generation || !dlg.isShowing) return@post
                    if (!loaded) showStatus("Загрузка списка приложений…")
                    else render(rows)
                }
            }
        }

        search.addTextChangedListener(object : android.text.TextWatcher {
            override fun beforeTextChanged(a: CharSequence?, b: Int, c: Int, d: Int) { }
            override fun onTextChanged(a: CharSequence?, b: Int, c: Int, d: Int) { }
            override fun afterTextChanged(e: android.text.Editable?) { refresh(e?.toString()) }
        })
        showStatus("Загрузка списка приложений…")
        dlg.show()
        executor.execute {
            val list = try { AppCatalog.load(ctx, force = true) } catch (e: Exception) { emptyList() }
            main.post {
                if (!dlg.isShowing) return@post
                all = list
                loaded = true
                if (list.isEmpty()) showStatus("Не удалось прочитать список приложений")
                else refresh(search.text?.toString())
            }
        }
    }
}

