 package app.yomikaioverlay

 import android.app.Activity
 import android.content.Intent
 import android.graphics.Color
 import android.graphics.drawable.GradientDrawable
 import android.net.Uri
 import android.os.Bundle
 import android.os.Handler
 import android.os.Looper
 import android.provider.Settings
 import android.util.TypedValue
 import android.view.Gravity
 import android.widget.Button
 import android.widget.LinearLayout
 import android.widget.ScrollView
 import android.widget.TextView
 import android.widget.Toast
 import app.yomikaioverlay.ot.AppCatalog
 import java.util.concurrent.Executors

 class MainActivity : Activity() {

     private lateinit var status: TextView
     private lateinit var btnToggle: Button
     private lateinit var engBtn: Button
     private lateinit var genderBtn: Button
     private lateinit var rateBtn: Button
     private lateinit var modeBtn: Button

     override fun onCreate(savedInstanceState: Bundle?) {
         super.onCreate(savedInstanceState)
         buildUi()
     }

     override fun onResume() {
         super.onResume()
         refresh()
     }

     private fun dp(v: Int) = TypedValue.applyDimension(
         TypedValue.COMPLEX_UNIT_DIP, v.toFloat(), resources.displayMetrics
     ).toInt()

     private fun rounded(color: Int, rdp: Int) = GradientDrawable().apply {
         setColor(color)
         cornerRadius = dp(rdp).toFloat()
     }

     private fun askNotifPermission() {
         if (android.os.Build.VERSION.SDK_INT >= 33) {
             try {
                 if (checkSelfPermission("android.permission.POST_NOTIFICATIONS") != android.content.pm.PackageManager.PERMISSION_GRANTED) {
                     requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"), 7)
                 }
             } catch (e: Exception) { }
         }
     }

     private fun buildUi() {
         askNotifPermission()
         val root = ScrollView(this)
         val col = LinearLayout(this).apply {
             orientation = LinearLayout.VERTICAL
             setPadding(dp(20), dp(24), dp(20), dp(24))
         }
         root.setBackgroundColor(Color.parseColor("#14161B"))

         val title = TextView(this).apply {
             text = getString(R.string.app_name)
             textSize = 22f
             setTextColor(Color.parseColor("#EEEFF3"))
             gravity = Gravity.CENTER
             setPadding(0, 0, 0, dp(16))
         }
         col.addView(title)

         status = TextView(this).apply {
             textSize = 14f
             setTextColor(Color.parseColor("#AFC0D8"))
             setPadding(0, 0, 0, dp(16))
         }
         col.addView(status)

         fun bigBtn(label: String, onClick: () -> Unit): Button {
             val b = Button(this)
             b.text = label
             b.setTextColor(Color.parseColor("#EEEFF3"))
             b.background = rounded(Color.parseColor("#3D404C"), 12)
             val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(54))
             lp.setMargins(0, 0, 0, dp(12))
             b.layoutParams = lp
             b.setOnClickListener { onClick() }
             col.addView(b)
             return b
         }

         fun prefs() = getSharedPreferences("ovr", MODE_PRIVATE)

         val sect = TextView(this).apply {
             text = "Настройки (те же, что в меню пузыря):"
             textSize = 15f
             setTextColor(Color.parseColor("#EEEFF3"))
             setPadding(0, 0, 0, 8)
         }
         col.addView(sect)

         engBtn = bigBtn("Движок: …") {
             val p = prefs()
             val cur = p.getString("ocr_engine", app.yomikaioverlay.ot.Engines.LENS)
             p.edit().putString("ocr_engine", app.yomikaioverlay.ot.Engines.next(cur)).apply()
             refresh()
         }
         genderBtn = bigBtn("Голос: …") {
             val p = prefs()
             val cur = p.getString("gender", "female")
             p.edit().putString("gender", if (cur == "male") "female" else "male").apply()
             refresh()
         }
         rateBtn = bigBtn("Скорость: …") {
             val p = prefs()
             val next = app.yomikaioverlay.ot.Rates.nextCycle(p.getFloat("rate", 1.0f))
             p.edit().putFloat("rate", next).apply()
             refresh()
         }

         // Режимы чтения: лайв, обычный, перевод, субтитры, манга/комикс/манхва/маньхуа
         modeBtn = bigBtn("Режим: …") {
             val p = prefs()
             val cur = app.yomikaioverlay.ot.ReadMode.normalize(
                 p.getString("read_mode", app.yomikaioverlay.ot.ReadMode.DEFAULT)
             )
             val next = app.yomikaioverlay.ot.ReadMode.next(cur)
             val order = app.yomikaioverlay.ot.ReadMode.order(next)
             val tr = app.yomikaioverlay.ot.ReadMode.translate(next)
             p.edit().putString("read_mode", next).apply()
             p.edit().putString("read_order", order).apply()
             if (tr != null) p.edit().putBoolean("translate", tr).apply()
             refresh()
         }

         // Список приложений устройства — запуск в один тап, без поиска в лаунчере
         bigBtn("Приложения (запуск из списка)") {
             showApps()
         }

         // Онлайн-ключи движков (не обязательны для Lens/Zen)
         val ep = app.yomikaioverlay.ot.EnginePrefs
         fun keyRow(label: String, getter: () -> String, setter: (String) -> Unit) {
             val et = android.widget.EditText(this).apply {
                 hint = label
                 setText(getter())
                 setTextColor(Color.parseColor("#EEEFF3"))
                 setHintTextColor(Color.parseColor("#7784A0"))
                 setBackgroundColor(Color.parseColor("#1E2129"))
                 setPadding(dp(12), 0, dp(12), 0)
                 textSize = 13f
             }
             val lp2 = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(48))
             lp2.setMargins(0, 0, 0, 8)
             et.layoutParams = lp2
             col.addView(et)
             et.addTextChangedListener(object : android.text.TextWatcher {
                 override fun beforeTextChanged(a: CharSequence?, b: Int, c: Int, d: Int) {}
                 override fun onTextChanged(a: CharSequence?, b: Int, c: Int, d: Int) {}
                 override fun afterTextChanged(a: android.text.Editable?) { setter(a?.toString() ?: "") }
             })
         }
         keyRow("Google AI (Gemini) ключ — необязательно", { ep.googleApiKey(this) }, { ep.setGoogleApiKey(this, it) })
         keyRow("OpenRouter ключ — необязательно", { ep.openrouterKey(this) }, { ep.setOpenrouterKey(this, it) })

         btnToggle = bigBtn("▶ Запустить оверлей") {
             if (OverlayService.running) {
