             // область МЕНЬШЕ экрана — тогда VirtualDisplay ужимает кадр целиком,
             // и все координаты блоков съезжают вверх (ошибка растёт с
             // расстоянием от верха экрана).
             try {
                 val dm = getSystemService(DisplayManager::class.java)
                 val d = dm?.getDisplay(Display.DEFAULT_DISPLAY)
                 val m = d?.mode
                 if (m != null && m.physicalWidth > 0 && m.physicalHeight > 0) {
                     return Point(m.physicalWidth, m.physicalHeight)
                 }
             } catch (e: Exception) { }
             if (Build.VERSION.SDK_INT >= 30) {
                 val b = wm.currentWindowMetrics.bounds
                 if (b.width() > 0 && b.height() > 0) return Point(b.width(), b.height())
             }
             val p = Point()
             @Suppress("DEPRECATION")
             wm.defaultDisplay.getRealSize(p)
             if (p.x <= 0 || p.y <= 0) {
                 val dm2 = resources.displayMetrics
                 p.set(dm2.widthPixels, dm2.heightPixels)
             }
             p
         } catch (e: Exception) {
             val dm = resources.displayMetrics
             Point(dm.widthPixels, dm.heightPixels)
         }
     }

