     // --- Пузырь: тап = меню; тянуть = переместить ---
     private fun attachBubbleTouch(b: View) {
         val slop = ViewConfiguration.get(this).scaledTouchSlop
         var downX = 0f
         var downY = 0f
         var startX = 0
         var startY = 0
         var moved = false
         b.setOnTouchListener { v, ev ->
             val lp = mainLp ?: return@setOnTouchListener false
             when (ev.actionMasked) {
                 MotionEvent.ACTION_DOWN -> {
                     downX = ev.rawX
                     downY = ev.rawY
                     startX = lp.x
                     startY = lp.y
                     moved = false
                     true
                 }
                 MotionEvent.ACTION_MOVE -> {
                     val dx = ev.rawX - downX
                     val dy = ev.rawY - downY
                     if (!moved && (Math.abs(dx) > slop || Math.abs(dy) > slop)) moved = true
                     if (moved) {
                         val s = screenSize()
                         lp.x = clamp(startX + dx.toInt(), 0, s.x - v.width)
                         lp.y = clamp(startY + dy.toInt(), 0, s.y - v.height)
                         try { wm.updateViewLayout(mainRoot, lp) } catch (e: Exception) { }
                         placeStopButton()
                     }
                     true
                 }
                 MotionEvent.ACTION_UP -> {
                     if (!moved) toggleExpanded()
                     moved = false
                     v.performClick()
                     true
                 }
                 else -> false
             }
         }
     }

     private fun clamp(v: Int, lo: Int, hi: Int) = if (v < lo) lo else if (v > hi) hi else v

     // ------------------------------------------------------------------
     // Рамка OCR-области
     // ------------------------------------------------------------------

     private fun regionRatio(): Rect {
         val l = prefs.getFloat("reg_l", Region.DEFAULT_RATIOS[0])
         val t = prefs.getFloat("reg_t", Region.DEFAULT_RATIOS[1])
         val r = prefs.getFloat("reg_r", Region.DEFAULT_RATIOS[2])
         val b = prefs.getFloat("reg_b", Region.DEFAULT_RATIOS[3])
         val s = screenSize()
         val box = Region.boxFromRatios(l, t, r, b, s.x, s.y)
         return Rect(box.left, box.top, box.right, box.bottom)
     }

     private fun regionPreset(): String =
         Region.normalizePreset(prefs.getString("reg_preset", Region.PRESET_BOTTOM))

     /** Высота системной строки статуса (там часы) — её нельзя сканировать. */
     private fun statusBarHeight(): Int {
         val id = resources.getIdentifier("status_bar_height", "dimen", "android")
         return if (id > 0) resources.getDimensionPixelSize(id) else dp(24)
     }

     /** Высота системной панели навигации/жеста — тоже не текст для чтения. */
     private fun navBarHeight(): Int {
         val id = resources.getIdentifier("navigation_bar_height", "dimen", "android")
         return if (id > 0) resources.getDimensionPixelSize(id) else 0
     }

     /** Реальная область OCR и рисования: рамка без строки статуса и навбара. */
     private fun ocrRect(): Rect {
         val r = regionRatio()
         val s = screenSize()
         val top = maxOf(r.top, statusBarHeight())
         val bottom = minOf(r.bottom, (s.y - navBarHeight()).coerceAtLeast(top + 1))
         return Rect(r.left, top, r.right, bottom)
     }

     private fun saveRegionRatio(rectPx: Rect, preset: String? = null) {
         val s = screenSize()
         val ratios = Region.ratiosOf(
             Region.Box(rectPx.left, rectPx.top, rectPx.right, rectPx.bottom), s.x, s.y,
         )
         prefs.edit()
             .putFloat("reg_l", ratios[0])
             .putFloat("reg_t", ratios[1])
             .putFloat("reg_r", ratios[2])
             .putFloat("reg_b", ratios[3])
             .putString("reg_preset", preset ?: Region.PRESET_CUSTOM)
             .apply()
         refreshFrame()
         rebuildPanel()
     }

     private fun regionLabel(): String = Region.label(regionPreset())

     private fun cycleRegionPreset() {
         val s = screenSize()
         val next = Region.nextPreset(regionPreset())
         val box = Region.rectFor(next, s.x, s.y)
         setPreset(next, box)
     }

     private fun setPreset(name: String, box: Region.Box) {
         prefs.edit().putString("reg_preset", name).apply()
         saveRegionRatio(Rect(box.left, box.top, box.right, box.bottom), name)
         frameView?.invalidate()
     }

     private var scanningFrame = false

     private fun refreshFrame() {
         frameView?.visibility =
             if (!hiddenSnooze && (expanded || autoReading || scanningFrame || speaking)) View.VISIBLE else View.GONE
         frameView?.invalidate()
     }

     /** Подсветка озвучиваемого участка должна следовать за [speaking]. */
     private fun setSpeaking(v: Boolean) {
         if (speaking != v) {
             speaking = v
             refreshFrame()
             // Кнопка «Стоп» нужна всегда, когда говорят, — и при авточтении,
             // и при разовом озвучивании скана.
             if (v) showStopButton() else if (!autoReading) hideStopButton()
         }
     }

     private inner class RegionFrameView : View(this@OverlayService) {
         private val p = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.STROKE
             strokeWidth = dp(2.5f).toFloat()
             color = frameRed
             pathEffect = DashPathEffect(floatArrayOf(20f, 12f), 0f)
         }
         // «Облачко» над текстом: скруглённый прямоугольник с заливкой + хвостик.
         private val bubbleFill = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.FILL
             color = Color.parseColor("#33FFFFFF")
         }
         private val bubbleFillActive = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.FILL
             color = Color.parseColor("#59FFC24C")
         }
         private val bubbleStroke = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.STROKE
             strokeWidth = dp(1.8f).toFloat()
             color = Color.parseColor("#E6FFFFFF")
         }
         private val bubbleStrokeActive = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.STROKE
             strokeWidth = dp(2.6f).toFloat()
             color = btnBgAccent
         }
         private val badgeBg = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             color = Color.parseColor("#CC000000")
         }
         private val badgeBgActive = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             color = btnBgAccent
         }
         private val badgeText = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             color = Color.WHITE
             textSize = dp(11f).toFloat()
             textAlign = Paint.Align.CENTER
             typeface = android.graphics.Typeface.DEFAULT_BOLD
         }
         private val badgeTextActive = Paint(badgeText).apply {
             color = Color.parseColor("#16181D")
         }
         private val corner = dp(7f).toFloat()
         private val radius = dp(9f).toFloat()

         override fun onDraw(c: Canvas) {
             val r = ocrRect()
             val l = r.left + 2f
             val t = r.top + 2f
             val rt = r.right - 2f
             val rb = r.bottom - 2f
             // Внешняя рамка области — тонко, без заливки.
             c.drawRect(l, t, rt, rb, p)
             // «Облачка» над реально распознанным текстом — только пока идёт
             // скан/чтение. При открытом меню не рисуем: панель сама лежит
             // поверх контента, и облачка попадали бы прямо на кнопки.
             val blocks = layoutBlocks
             if (!expanded && blocks.isNotEmpty() &&
                 (scanningFrame || speaking || autoReading ||
                     SystemClock.elapsedRealtime() < bubbleUntil)
             ) {
                 for (i in blocks.indices) {
                     val b = blocks[i]
-                    if (b.width() <= 0 || b.height() <= 0) continue
+                    if (b.width <= 0 || b.height <= 0) continue
                     val active = i == activeBlock
                     val pad = dp(4).toFloat()
                     val x0 = b.left.toFloat() - pad
                     val y0 = b.top.toFloat() - pad + boxShiftY
                     val x1 = b.right.toFloat() + pad
                     val y1 = b.bottom.toFloat() + pad + boxShiftY
                     c.drawRoundRect(x0, y0, x1, y1, corner, corner, if (active) bubbleFillActive else bubbleFill)
                     // хвостик облачка снизу по центру
                     val bx = (x0 + x1) / 2f
                     tailPath.reset()
                     tailPath.moveTo(bx - dp(6f), y1 - dp(1f))
                     tailPath.lineTo(bx + dp(6f), y1 - dp(1f))
                     tailPath.lineTo(bx, y1 + dp(7f))
                     tailPath.close()
                     c.drawPath(tailPath, if (active) bubbleFillActive else bubbleFill)
                     c.drawRoundRect(x0, y0, x1, y1, corner, corner, if (active) bubbleStrokeActive else bubbleStroke)
                     drawBadge(c, i + 1, x0, y0, active)
                 }
             }
         }

         private val tailPath = Path()

         private fun drawBadge(c: Canvas, num: Int, x0: Float, y0: Float, active: Boolean) {
             val cx = x0 + radius
             val cy = y0 + radius
             c.drawCircle(cx, cy, radius, if (active) badgeBgActive else badgeBg)
             c.drawText(num.toString(), cx, cy + dp(3.7f).toFloat(), if (active) badgeTextActive else badgeText)
         }
     }

