     private fun renderAppList(
         apps: List<AppCatalog.App>,
         shown: List<AppCatalog.App>,
         icons: Map<String, android.graphics.drawable.Drawable?>,
     ) {
         val box = appListBox ?: return
         box.removeAllViews()
         if (apps.isEmpty()) {
             box.addView(TextView(this).apply {
                 text = "Ничего не найдено"
                 textSize = 13f
                 setTextColor(txtSub)
                 setPadding(dp(6), dp(12), dp(6), dp(12))
             })
             return
         }
         for (a in shown) {
             val row = LinearLayout(this).apply {
                 orientation = LinearLayout.HORIZONTAL
                 gravity = Gravity.CENTER_VERTICAL
                 setPadding(dp(6), dp(8), dp(6), dp(8))
                 setOnClickListener {
                     closeAppPanel()
                     AppCatalog.launch(this@OverlayService, a)
                 }
             }
             val icon = icons[a.pkg]
             if (icon != null) {
                 row.addView(ImageView(this).apply {
                     setImageDrawable(icon)
                     layoutParams = LinearLayout.LayoutParams(dp(34), dp(34)).apply {
                         rightMargin = dp(10)
                     }
                 })
             } else {
                 row.addView(View(this).apply {
                     layoutParams = LinearLayout.LayoutParams(dp(34), dp(34)).apply { rightMargin = dp(10) }
                 })
             }
             row.addView(LinearLayout(this).apply {
                 orientation = LinearLayout.VERTICAL
                 addView(TextView(this@OverlayService).apply {
                     text = a.label
                     textSize = 14f
                     setTextColor(txtTitle)
                     maxLines = 1
                 })
                 addView(TextView(this@OverlayService).apply {
                     text = a.pkg
                     textSize = 10f
                     setTextColor(txtSub)
                     maxLines = 1
                 })
             })
             box.addView(row)
         }
         if (apps.size > shown.size) {
             box.addView(TextView(this).apply {
                 text = "…и ещё ${apps.size - shown.size}. Уточните поиск."
                 textSize = 11f
                 setTextColor(txtSub)
                 setPadding(dp(6), dp(8), dp(6), 0)
             })
         }
     }

     private fun closeAppPanel() {
         try { appWin?.let { wm.removeView(it) } } catch (e: Exception) { }
         appWin = null
         appLp = null
         appListBox = null
         appListGen++ // отменить запоздалый рендер из фонового потока
     }

     /** Дописать распознанный фрагмент в буфер авточтения и показать его снизу. */
     private fun appendRead(text: String) {
         if (readBuffer.isNotEmpty()) readBuffer.append('\n')
         readBuffer.append(text)
         if (readBuffer.length > 6000) readBuffer.delete(0, readBuffer.length - 6000)
         preview = readBuffer.toString().trim()
         previewText?.text = preview
         previewText?.post { previewText?.let { v -> v.scrollTo(0, v.layout?.height ?: 0) } }
     }

     private fun circle(sizeDp: Int, bgColor: Int): View {
         val v = View(this)
         v.background = rounded(bgColor, sizeDp / 2f)
         v.layoutParams = LinearLayout.LayoutParams(dp(sizeDp), dp(sizeDp))
         return v
     }

     private fun iconBtn(iconRes: Int?, glyph: String?, bgColor: Int, onClick: () -> Unit): FrameLayout {
         val f = FrameLayout(this)
         val size = dp(40f)
         f.layoutParams = LinearLayout.LayoutParams(size, size)
         f.background = rounded(bgColor, 20f)
         f.isClickable = true
         if (iconRes != null) {
             val iv = ImageView(this)
             iv.setImageResource(iconRes)
             val lp = FrameLayout.LayoutParams(dp(22f), dp(22f))
             lp.gravity = Gravity.CENTER
             iv.layoutParams = lp
             f.addView(iv)
         } else if (glyph != null) {
             val tv = TextView(this)
             tv.text = glyph
             tv.textSize = 16f
             tv.setTextColor(txtTitle)
             tv.gravity = Gravity.CENTER
             tv.layoutParams = FrameLayout.LayoutParams(
                 FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT
             )
             f.addView(tv)
         }
         f.setOnClickListener { runCatching(onClick) }
         return f
     }

