     /**
      * Прячет все окна оверлея на время захвата экрана. Раньше скрывались
      * только пузырь и рамка — окно выбора голоса/рамки с затемнением
      * попадало в скриншот и ломало OCR.
      */
     private fun setOverlayAlpha(alpha: Float) {
         ui.post {
             try {
                 mainRoot?.alpha = alpha
                 frameView?.alpha = alpha
                 voiceWin?.alpha = alpha
                 miniWin?.alpha = alpha
