     /**
      * Создаёт VirtualDisplay + ImageReader ОДИН раз на сессию MediaProjection.
      * Повторный createVirtualDisplay() на том же MediaProjection с Android 14
      * запрещён (SecurityException) — поэтому дальше только читаем кадры.
      */
     private fun bindProjection(mp: MediaProjection) {
         releaseDisplay()
         val s = screenSize()
         val density = resources.displayMetrics.densityDpi
         var r: ImageReader? = null
         try {
             r = ImageReader.newInstance(s.x, s.y, PixelFormat.RGBA_8888, 2)
             val vd = mp.createVirtualDisplay(
                 "ocr-scan", s.x, s.y, density,
                 DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                 r.surface, null, ui,
             )
             reader = r
             vDisplay = vd
             displaySize = Point(s.x, s.y)
         } catch (e: Exception) {
             try { r?.close() } catch (_: Exception) { }
             android.util.Log.w("OcrCap", "bindProjection: ${e.message}")
             ui.post {
                 preview = "⚠ Не удалось начать захват экрана — разрешите заново"
                 previewText?.text = preview
                 notifyStatus(preview)
             }
         }
     }

     private fun releaseDisplay() {
         try { vDisplay?.release() } catch (e: Exception) { }
         vDisplay = null
         try { reader?.close() } catch (e: Exception) { }
         reader = null
         displaySize = Point(0, 0)
     }

     /**
      * Если экран повернулся, к тому же VirtualDisplay подключаем новый ImageReader
      * нужного размера (resize + setSurface). Новый VirtualDisplay создать нельзя,
      * поэтому меняем только поверхность.
      */
     private fun rebindSurface(w: Int, h: Int): Boolean {
         val vd = vDisplay ?: return false
         var newReader: ImageReader? = null
         return try {
             newReader = ImageReader.newInstance(w, h, PixelFormat.RGBA_8888, 2)
             vd.resize(w, h, resources.displayMetrics.densityDpi)
             vd.setSurface(newReader.surface)
             val old = reader
             reader = newReader
             try { old?.close() } catch (e: Exception) { }
             displaySize = Point(w, h)
             true
         } catch (e: Exception) {
             try { newReader?.close() } catch (_: Exception) { }
             android.util.Log.w("OcrCap", "rebindSurface: ${e.message}")
             false
         }
     }

     /** Свежий полноэкранный кадр из уже открытого ImageReader (пиксель-в-пиксель). */
     private fun grabFrame(): Bitmap? {
         val s = screenSize()
         if (reader == null || s.x != displaySize.x || s.y != displaySize.y) {
             if (!rebindSurface(s.x, s.y)) return null
         }
         val rd = reader ?: return null
         return try {
             // ВАЖНО: acquireNextImage() блокируется НАВСЕГДА, если новых кадров
             // не будет (экран статичен и MediaProjection не пушит кадры). Раньше
             // здесь вставал рабочий поток и авточтение зависало. Поэтому ждём
             // кадр недолго и при таймауте просто возвращаем null.
             val deadline = SystemClock.elapsedRealtime() + FRAME_WAIT_MS
             var img: android.media.Image? = rd.acquireLatestImage()
             while (img == null && SystemClock.elapsedRealtime() < deadline) {
                 SystemClock.sleep(40)
                 img = rd.acquireLatestImage()
             }
             val im = img ?: return null
             try {
                 val plane = im.planes[0]
                 val buf = plane.buffer
                 val pixelStride = plane.pixelStride
                 val rowStride = plane.rowStride
                 // На части устройств rowStride < pixelStride*w (не должно, но бывает):
                 // страховка от createBitmap с отрицательной шириной.
                 val rowPadding = (rowStride - pixelStride * s.x).coerceAtLeast(0)
                 val rawWidth = (s.x + rowPadding / pixelStride).coerceAtLeast(s.x)
                 val raw = Bitmap.createBitmap(rawWidth, s.y, Bitmap.Config.ARGB_8888)
                 buf.rewind()
                 raw.copyPixelsFromBuffer(buf)
                 val exact = Bitmap.createBitmap(raw, 0, 0, s.x, s.y)
                 raw.recycle()
                 exact
             } finally {
                 im.close()
             }
         } catch (e: Exception) {
             null
         }
     }

     private fun captureRegion(): Bitmap? {
         if (projection == null || reader == null) return null
         // VirtualDisplay с AUTO_MIRROR зеркалит ВЕСЬ экран и СЖИМАЕТ его под
         // размер выдачи: раньше экран целиком ужимался в размер рамки, текст
         // мельчал до неузнаваемости и детектор не находил строк («текст не
         // найден в рамке»). Поэтому захват всегда полноэкранный, а рамка
         // вырезается из полученного кадра — как это делает overlay-translator.
         val full = try {
             setOverlayAlpha(0.0f)
             Thread.sleep(180)
             grabFrame()
         } catch (e: Exception) {
             null
         } finally {
             setOverlayAlpha(1f)
         } ?: return null
         val r = ocrRect()
         val l = r.left.coerceIn(0, full.width - 1)
         val t = r.top.coerceIn(0, full.height - 1)
         val cw = (r.right - r.left).coerceIn(8, full.width - l)
         val ch = (r.bottom - r.top).coerceIn(8, full.height - t)
         return try {
             Bitmap.createBitmap(full, l, t, cw, ch)
         } finally {
             full.recycle()
         }
     }

     private fun ocrScan(onText: (String) -> Unit) {
         ocrHandler.post {
             // Один захват за раз: два потока на одном ImageReader блокируют
             // друг друга и подвешивают чтение.
             if (!scanInFlight.compareAndSet(false, true)) {
                 android.util.Log.w("OcrCap", "scan skipped: previous still running")
                 onText("")
                 return@post
             }
             val now = SystemClock.elapsedRealtime()
             if (!scanThrottle.allow(now)) {
                 scanInFlight.set(false)
                 onText("")
                 return@post
             }
             try {
             var text = ""
             var hint: String? = null
-            var layoutRects: List<Rect> = emptyList()
+            var layoutRects: List<ReadingOrder.TextBox> = emptyList()
             try {
                 val bmp = captureRegion()
                 if (bmp == null) {
                     // Кадр не пришёл: от «нет текста» это отличается и раньше
                     // выглядело одинаково. Отдаём понятную причину.
                     hint = if (!projectionGranted || projection == null)
                         "⚠ Захват экрана выключен — нажмите «Скан», чтобы разрешить заново"
                     else
                         "⚠ Не удалось получить кадр экрана — повторите скан"
                 } else {
                     val keyHint = engineKeyHint()
                     if (keyHint != null) {
                         hint = "⚠ " + engineTitle() + ": " + keyHint
                     } else {
                         text = try {
                             when (engineId()) {
                                 Engines.ZEN -> zenOcr.recognizeText(bmp)
                                 Engines.GOOGLE_AI -> googleOcr.recognizeText(bmp)
                                 Engines.OPENROUTER -> orOcr.recognizeText(bmp)
                                 else -> glensOcr.recognizeText(bmp)
                             }
                         } catch (e: Exception) {
                             android.util.Log.w("OcrNet", engineId() + ": " + e.message)
                             ""
                         }
                     }
                     // Гибрид: блоки текста (рамки и порядок чтения) — на устройстве.
                     val lay = computeLayout(bmp)
                     layoutRects = lay.blocks
                     // recycle() только если ML Kit гарантированно отпустил
                     // битмап: на таймауте он ещё читает его в нативе.
                     if (!lay.bitmapInUse) {
                         try { bmp.recycle() } catch (e: Exception) { }
                     }
                 }
             } catch (e: Exception) { }
             var out = text.replace(wsRe, " ").trim()
             // Перевод по направлению: латиница → русский, кириллица → английский.
             val transOn = prefs.getBoolean("translate", false)
             val tdir = prefs.getString("translate_dir", TransDir.AUTO) ?: TransDir.AUTO
             if (transOn && TransDir.shouldTranslate(out, tdir)) {
                 val target = if (TransDir.normalize(tdir) == TransDir.RU2EN) "en" else "ru"
                 try {
                     val tr = translator.translate(out, EnginePrefs.TR_AUTO, EnginePrefs.MODE_ONLINE, target)
                     if (!tr.isNullOrBlank() && tr != out) out = tr
                 } catch (e: Exception) {
                     android.util.Log.d("OcrTr", "translate: " + e.message)
                 }
             }
             ui.post {
                 if (layoutRects.isNotEmpty() || out.isNotBlank()) {
                     stopBoxAnim()
                     layoutBlocks = layoutRects
                     // Облачка гаснут через 4 с, если чтение не идёт: под ними
                     // мог уже появиться другой экран, и они «залипали» бы.
                     bubbleUntil = SystemClock.elapsedRealtime() + 4000L
                     ui.removeCallbacks(bubbleHide)
                     ui.postDelayed(bubbleHide, 4100L)
                     activeBlock = if (autoReading) 0 else -1
                     refreshFrame()
                     if (expanded) rebuildPanel()
                 }
                 if (hint != null && out.isBlank()) {
                     preview = hint
                     previewText?.text = preview
                 }
                 onText(out)
             }
             } finally {
                 scanInFlight.set(false)
             }
         }
     }

     /** ML Kit: блоки текста на битмапе → координаты экрана, порядок чтения. */
-    private fun computeLayout(bmp: Bitmap): LayoutResult<Rect> {
+    private fun computeLayout(bmp: Bitmap): LayoutResult<ReadingOrder.TextBox> {
         if (layoutOcr == null) {
             layoutOcr = try { LayoutOcr() } catch (e: Throwable) { null }
         }
         val lo = layoutOcr
         if (lo == null || !lo.isAvailable) {
-            return LayoutResult(emptyList<Rect>(), bitmapInUse = false)
+            return LayoutResult(emptyList<ReadingOrder.TextBox>(), bitmapInUse = false)
         }
         val r = ocrRect()
         val w = bmp.width.toFloat().coerceAtLeast(1f)
         val h = bmp.height.toFloat().coerceAtLeast(1f)
         val rw = (r.right - r.left)
         val rh = (r.bottom - r.top)
         val res: LayoutResult<LayoutBlock> = try {
             lo.blocks(bmp)
         } catch (e: Throwable) {
             // Исключение — результат неизвестен, битмап отдаём наверх не трогая.
             LayoutResult(emptyList<LayoutBlock>(), bitmapInUse = true)
         }
         val mapped = res.blocks.map { b ->
             val bx = b.rect
-            Rect(
+            ReadingOrder.TextBox(
                 r.left + (bx.left / w * rw).toInt(),
                 r.top + (bx.top / h * rh).toInt(),
                 r.left + (bx.right / w * rw).toInt(),
                 r.top + (bx.bottom / h * rh).toInt()
             )
         }
         return LayoutResult(
             ReadingOrder.order(mapped, readOrderMode()),
             res.bitmapInUse,
         )
     }

