     font-weight: bold;
 }

 ul, ol, dl {
     list-style-position: outside;
     line-height: 1.6;
     padding: 0;
     margin: 0 0 0 20px;
     list-style-type: none;
 }

 li {
     line-height: 2;
 }

 a {
     color: #1DA2BD;
     text-decoration: none;
     transition: all 0.3s ease, visibility 0s;
 }

 a:hover {
     color: #35c1e4;
 }

