     background-color: #f7f7f8;
     border-radius: 4px;
     font-size: 1em;
     line-height: 1.45;
     margin-bottom: 1.25em;
     overflow-x: auto;
     padding: 1rem;
 }

 li em, p em {
     padding: 0 1px;
 }

