package app.yomikaioverlay.ot

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Регрессии на [RuText.stripWrappers] — чистку, которую применяют к ответам
 * LLM на НЕИЗВЕСТНОМ языке (OCR с латиницей/японским, перевод в EN).
 *
 * Раньше postChatFull прогонял через [RuText.clean] вообще всё, и
 * `clean("Hello world")` возвращал пустую строку: английский OCR не работал
 * ни в одном движке, а перевод RU→EN вычищался до ничего.
 */
class RuTextWrappersTest {

    @Test
    fun `латиница не вычищается`() {
        assertEquals("Hello world", RuText.stripWrappers("Hello world"))
    }

    @Test
    fun `смешанный текст с кириллицей сохраняется целиком`() {
        assertEquals("Привет Hello мир", RuText.stripWrappers("Привет Hello мир"))
    }

    @Test
    fun `японский иероглифы не трогаются`() {
        assertEquals("こんにちは世界", RuText.stripWrappers("こんにちは世界"))
    }

    @Test
    fun `длинное английское предложение не обрезается`() {
        val text = "The door creaks open and the wind howls outside"
        assertEquals(text, RuText.stripWrappers(text))
    }

    @Test
    fun `снимает приписки LLM`() {
        assertEquals("Открыта дверь", RuText.stripWrappers("Here is: Открыта дверь"))
        assertEquals("Открыта дверь", RuText.stripWrappers("Перевод: Открыта дверь"))
    }

    @Test
    fun `снимает приписки подряд`() {
        assertEquals("Open the door", RuText.stripWrappers("Here is the translation: Open the door"))
    }

    @Test
    fun `разбирает markdown-забор`() {
        assertEquals("Open the door", RuText.stripWrappers("```\nOpen the door\n```"))
        assertEquals("Open the door", RuText.stripWrappers("```text\nOpen the door\n```"))
    }

    @Test
    fun `не трогает ё — это не русская чистка`() {
        // clean() делает ё→е, stripWrappers() не должен: OCR обязан вернуть
        // текст как на экране.
        assertEquals("Ёлка", RuText.stripWrappers("Ёлка"))
    }

    @Test
    fun `пустой ввод`() {
        assertEquals("", RuText.stripWrappers(""))
        assertEquals("", RuText.stripWrappers("   \n  "))
    }

    @Test
    fun `clean по-прежнему чистит русский — включая ё→е и заборы`() {
        assertEquals("Елка", RuText.clean("```\nЁлка\n```"))
    }

    @Test
    fun `clean по-прежнему выкидывает латиницу из русской строки`() {
        val out = RuText.clean("Привет мир Hello world")
        assertFalse(out.contains("Hello"))
        assertTrue(out.contains("Привет"))
    }
}

package app.yomikaioverlay.ot

import android.graphics.Rect
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Регрессия на [ReadingOrder.rows] / [ReadingOrder.columns]: полосы должны
 * строиться по НАКОПЛЕННЫМ границам полосы, а не по её первому элементу.
 *
 * Старая проверка `overlap(members.first(), r)` рвала одну строку надвое,
 * как только очередной блок переставал пересекаться с якорем, но всё ещё
 * пересекался с хвостом полосы.
 */
class ReadingOrderBandTest {

    private fun key(r: Rect) = "${r.left},${r.top},${r.right},${r.bottom}"

    private fun keys(rects: List<Rect>) = rects.map { key(it) }

    @Test
    fun `строка не рвётся на части`() {
        // Полоса растёт вниз: якорь top=0..100, второй блок top=90..200.
        val a = Rect(0, 0, 100, 100)
        val b = Rect(0, 90, 100, 200)
        // Третий пересекает И b (90..200), но почти не якорь (0..100).
        val c = Rect(0, 180, 100, 280)
        val rows = ReadingOrder.rows(listOf(a, b, c))
        assertEquals("блоки a,b,c должны попасть в одну полосу", 1, rows.size)
        assertEquals(keys(listOf(a, b, c)), keys(rows[0]))
    }

    @Test
    fun `далеко отстоящие блоки остаются разными строками`() {
        val a = Rect(0, 0, 100, 40)
        val b = Rect(0, 400, 100, 440)
        val rows = ReadingOrder.rows(listOf(a, b))
        assertEquals(2, rows.size)
    }

    @Test
    fun `частично перекрывающиеся строки объединяются`() {
        val a = Rect(0, 0, 100, 40)
        val b = Rect(0, 30, 100, 70)
        assertEquals(1, ReadingOrder.rows(listOf(a, b)).size)
    }

    @Test
    fun `колонки строятся по горизонтали и не сливаются`() {
        val left = Rect(0, 0, 50, 400)
        val right = Rect(300, 0, 350, 400)
        assertEquals(2, ReadingOrder.columns(listOf(left, right)).size)
    }

    @Test
    fun `колонка растёт вправо и не рвётся`() {
        val a = Rect(0, 0, 100, 100)
        val b = Rect(90, 0, 200, 100)
        val c = Rect(180, 0, 280, 100)
        val cols = ReadingOrder.columns(listOf(a, b, c))
        assertEquals(1, cols.size)
        assertEquals(keys(listOf(a, b, c)), keys(cols[0]))
    }

    @Test
    fun `пустой и одиночный ввод`() {
        assertEquals(0, ReadingOrder.rows(emptyList()).size)
        val one = Rect(1, 1, 2, 2)
        assertEquals(1, ReadingOrder.rows(listOf(one)).size)
        assertEquals(0, ReadingOrder.columns(emptyList()).size)
    }

    @Test
    fun `порядок входа не влияет на разбивку`() {
        val a = Rect(0, 0, 100, 100)
        val b = Rect(0, 90, 100, 200)
        val c = Rect(0, 180, 100, 280)
        val d = Rect(0, 500, 100, 600)
        assertEquals(
            keys(ReadingOrder.rows(listOf(a, b, c, d)).flatten()),
            keys(ReadingOrder.rows(listOf(d, c, b, a)).flatten()),
        )
    }

    @Test
    fun `ltr по сгруппированной строке идёт слева направо`() {
        val left = Rect(0, 0, 40, 40)
        val right = Rect(60, 10, 100, 50)
        assertEquals(
            keys(listOf(left, right)),
            keys(ReadingOrder.order(listOf(right, left), ReadingOrder.LTR)),
        )
    }
}

