package app.yomikaioverlay.ot

import android.graphics.Rect

/**
 * Порядок чтения распознанных блоков текста: номера 1..N и направление.
 *
 * Геометрия живёт в чистом [TextBox], а не в `android.graphics.Rect`:
 * в JVM-тестах android.jar — заглушка, у которой `Rect.left()` возвращает 0,
 * поэтому любой тест на настоящих прямоугольниках проходил, ничего не
 * проверяя (весь набор вырождался в 0,0,0,0). Android-обёртки внизу файла
 * конвертируют [Rect] ↔ [TextBox] на границе.
 */
object ReadingOrder {
    const val AUTO = "auto"          // как вернул распознаватель
    const val LTR = "ltr"            // слева → направо, строки сверху вниз
    const val RTL = "rtl"            // справа → налево, строки сверху вниз
    const val VERTICAL = "vertical"  // колонки справа → налево, внутри сверху вниз
    const val BOTTOM_UP = "bottom_up" // снизу вверх, строки слева направо

    val MODES = listOf(AUTO, LTR, RTL, VERTICAL, BOTTOM_UP)
    const val DEFAULT = AUTO

    /** Прямоугольник блока текста в пикселях экрана — чистый, без Android. */
    data class TextBox(val left: Int, val top: Int, val right: Int, val bottom: Int) {
        val width: Int get() = right - left
        val height: Int get() = bottom - top
        val centerX: Int get() = (left + right) / 2
    }

    fun normalize(mode: String?): String = if (mode != null && mode in MODES) mode else DEFAULT

    fun label(mode: String?): String = when (normalize(mode)) {
        AUTO -> "Как распознано"
        LTR -> "→ слева направо"
        RTL -> "← справа налево"
        VERTICAL -> "↓ вертикально"
        BOTTOM_UP -> "↑ снизу вверх"
        else -> "Как распознано"
    }

    /** Краткое направление для заголовка кнопки. */
    fun short(mode: String?): String = when (normalize(mode)) {
        AUTO -> "Авто"
        LTR -> "→"
        RTL -> "←"
        VERTICAL -> "↓"
        BOTTOM_UP -> "↑"
        else -> "Авто"
    }

    fun next(mode: String?): String {
        val list = MODES
        return list[(list.indexOf(normalize(mode)) + 1) % list.size]
    }

    /** Блоки в порядке чтения 1..N по выбранному направлению. */
    fun order(boxes: List<TextBox>, mode: String?): List<TextBox> {
        if (boxes.size < 2) return boxes
        return when (normalize(mode)) {
            AUTO -> boxes
            LTR -> rows(boxes).flatMap { it.sortedBy { b -> b.left } }
            RTL -> rows(boxes).flatMap { it.sortedByDescending { b -> b.right } }
            BOTTOM_UP -> rows(boxes).reversed().flatMap { it.sortedBy { b -> b.left } }
            VERTICAL -> columns(boxes)
                .sortedByDescending { c -> c.first().centerX }
                .flatMap { it.sortedBy { b -> b.top } }
            else -> boxes
        }
    }

    /** Разбивает блоки на строки по вертикальному пересечению полос. */
    fun rows(boxes: List<TextBox>): List<List<TextBox>> = groupByBand(boxes, horizontal = true)

    /** Разбивает блоки на колонки по горизонтальному пересечению полос. */
    fun columns(boxes: List<TextBox>): List<List<TextBox>> = groupByBand(boxes, horizontal = false)

    /** Минимальная доля пересечения, чтобы блоки считались одной полосой. */
    private const val BAND_OVERLAP = 0.4f

    /**
     * Разбивает блоки на полосы по пересечению.
     *
     * Сравнение шло только с members.first() — якорем полосы. Блок, который
     * пересекал второй-третий элемент полосы, но не якорь, порождал лишнюю
     * полосу и абзац разрывался на две «строки». Теперь у полосы накопленные
     * границы, и перебор идёт с конца: текст идёт сверху вниз, поэтому чаще
     * всего блок попадает в последнюю полосу и цикл заканчивается первой же
     * проверкой (вместо always-first, как в firstOrNull).
     */
    private fun groupByBand(boxes: List<TextBox>, horizontal: Boolean): List<List<TextBox>> {
        val sorted = if (horizontal) boxes.sortedBy { it.top } else boxes.sortedBy { it.left }
        val bands = mutableListOf<MutableList<TextBox>>()
        val bandStart = mutableListOf<Int>()
        val bandEnd = mutableListOf<Int>()
        for (b in sorted) {
            val s = if (horizontal) b.top else b.left
            val e = if (horizontal) b.bottom else b.right
            var hit = -1
            for (i in bands.indices.reversed()) {
                val bs = bandStart[i]
                val be = bandEnd[i]
                val inter = minOf(be, e) - maxOf(bs, s)
                val minLen = minOf(be - bs, e - s)
                if (minLen > 0 && inter.toFloat() / minLen >= BAND_OVERLAP) {
                    hit = i
                    break
                }
            }
            if (hit < 0) {
                bands.add(mutableListOf(b))
                bandStart.add(s)
                bandEnd.add(e)
            } else {
                bands[hit].add(b)
                if (s < bandStart[hit]) bandStart[hit] = s
                if (e > bandEnd[hit]) bandEnd[hit] = e
            }
        }
        return bands
    }

    /** android.graphics.Rect → чистый тип (граница Android/чистой логики). */
    fun toBox(r: Rect): TextBox = TextBox(r.left, r.top, r.right, r.bottom)

    /** Чистый тип → android.graphics.Rect для отрисовки. */
    fun toRect(b: TextBox): Rect = Rect(b.left, b.top, b.right, b.bottom)
}

