package app.yomikaioverlay.ot

import android.content.Context
import android.graphics.Bitmap
import android.os.SystemClock

/**
 * «Zen Free» — бесплатный ИИ-хаб: перебирает модели [LlmClient.ZEN_FREE]
 * и берёт первую, ответившую текстом. Ключ не нужен.
 *
 * Если хаб недоступен (403/сеть/пустой ответ) — молча падаем на Google Lens,
 * который тоже бесключевой: пользователь всегда получает результат скана,
 * а не пустой экран.
 */
class ZenFreeOcrEngine(private val ctx: Context) : OcrEngine {

    private val fallbackGlens by lazy { GlensOcrEngine() }

    override fun recognizeText(image: Bitmap): String {
        // Без общего дедлайна перебор 5 моделей занимал до 250 с (connect+read
        // на модель) плюс фолбэк Lens — до 5 минут, в течение которых
        // scanInFlight=true и все следующие сканы отбрасывались. HandlerThread
        // при этом нельзя прервать из onDestroy, пока он в сети.
        val deadline = SystemClock.elapsedRealtime() + BUDGET_MS
        var interrupted = false
        for (model in LlmClient.ZEN_FREE) {
            // Thread.interrupted() СБРАСЫВАЕТ флаг, поэтому результат
            // запоминаем: иначе последующая проверка всегда давала бы false
            // и мы проваливались в дорогой фолбэк Lens.
            if (Thread.interrupted()) {
                interrupted = true
                break
            }
            val left = deadline - SystemClock.elapsedRealtime()
            // Остаток дедлайна уходит в сам запрос — иначе проверка бюджета
            // между моделями ничего не ограничивала: один ответ мог занять
            // connect+read = 50 с.
            if (left < MIN_SLICE_MS) break
            try {
                val result = LlmClient.visionFull(
                    image, model, russianOnly = false, scanMode = "rect",
                    timeoutMs = minOf(left, PER_MODEL_MS).toInt(),
                )
                if (result != null && result.text.isNotBlank()) {
                    if (result.totalTokens > 0) {
                        EnginePrefs.incrementTokens(ctx, result.totalTokens)
                    }
                    return result.text
                }
            } catch (e: Exception) {
                // следующая модель
            }
        }
        if (interrupted) return ""
        // Фолбэк тоже должен уложиться в бюджет.
        val lensLeft = deadline - SystemClock.elapsedRealtime()
        if (lensLeft < MIN_SLICE_MS) return ""
        val lens = try { fallbackGlens.recognizeText(image, minOf(lensLeft, LENS_MS).toInt()) } catch (e: Exception) { "" }
        if (lens.isNotBlank()) {
            EnginePrefs.incrementTokens(ctx, (lens.length * 1.5f).toLong().coerceAtLeast(15L))
        }
        return lens
    }

    override fun close() {
        fallbackGlens.close()
    }

    private companion object {
        /** Общий бюджет на один скан: перебор моделей + фолбэк Lens. */
        const val BUDGET_MS = 25_000L
        /** Потолок на одну модель, чтобы хаб не съел весь бюджет первой попыткой. */
        const val PER_MODEL_MS = 9_000L
        /** Потолок на фолбэк Lens. */
        const val LENS_MS = 12_000L
        /** Ниже этого остатка запрос не имеет смысла начинать. */
        const val MIN_SLICE_MS = 2_000L
    }
}

