fun setTokenUsageCount(ctx: Context, v: Long) {
        synchronized(tokenLock) {
            tokenCache.set(v)
            sp(ctx).edit().putLong("token_usage", v).apply()
        }
    }

    /**
     * Инкремент счётчика токенов.
     *
     * Счётчик пишут и поток OCR, и поток перевода; обычное
     * чтение-изменение-запись теряло одно из параллельных начислений.
     * apply() обязан быть ВНУТРИ замка: он синхронно меняет in-memory карту,
     * и запоздавшая запись меньшего значения перезатирала бы большее — и
     * prefs расходились бы с tokenCache.
     */
    fun incrementTokens(ctx: Context, plus: Long) {
        if (plus <= 0) return
        val prefs = sp(ctx)
        synchronized(tokenLock) {
            var cur = tokenCache.get()
            if (cur < 0L) {
                cur = prefs.getLong("token_usage", 0L)
            }
            val next = cur + plus
            tokenCache.set(next)
            prefs.edit().putLong("token_usage", next).apply()
        }
    }

