@Volatile
    private var words: Map<String, String>? = null

    /** Момент последней неудачной попытки — чтобы не читать assets на каждое слово. */
    private var failedAt = 0L

    private fun load(): Map<String, String> {
        words?.let { return it }
        return synchronized(this) {
            words?.let { return it }
            // Провал (I/O, OOM на много-мегабайтном JSON) не кэшируем
            // навсегда — раньше пустая карта сохранялась до перезапуска
            // процесса. Но и не повторяем на КАЖДОЕ слово: load() дёргается
            // и из isUsable(), и из каждого lookup(), то есть попытка
            // перечитывать весь 2-мегабайтный assets на каждую реплику.
            // Поэтому — короткий backoff.
            val now = SystemClock.elapsedRealtime()
            if (failedAt != 0L && now - failedAt < RETRY_AFTER_MS) return emptyMap()
            val loaded = runCatching {
                val raw = ctx.assets.open("dict/en_ru.json").bufferedReader()
                    .use { it.readText() }
                val obj = JSONObject(raw)
                val keys = obj.keys()
                val map = HashMap<String, String>((obj.length().toDouble() / 0.75f).toInt())
                while (keys.hasNext()) {
                    val k = keys.next()
                    map[k] = obj.getString(k)
                }
                map
            }.getOrNull()
            if (loaded != null) {
                words = loaded
                failedAt = 0L
            } else {
                failedAt = now
            }
            loaded ?: emptyMap()
        }
    }

    private companion object {
        /** Пауза перед повторной попыткой прочитать словарь после ошибки. */
        const val RETRY_AFTER_MS = 30_000L
    }

