private fun fillAppList(query: String?) {
        val box = appListBox ?: return
        val gen = ++appListGen
        box.removeAllViews()
        box.addView(TextView(this).apply {
            text = "Загрузка списка приложений…"
            textSize = 13f
            setTextColor(txtSub)
            setPadding(dp(6), dp(12), dp(6), dp(12))
        })
        val ctx = applicationContext
        val worker = appListWorker
        if (worker == null) return
        worker.post {
            // Один ПОСТОЯННЫЙ поток на панель, а не Thread на каждый символ:
            // 8 нажатий в поиске раньше поднимали 8 потоков × 60 вызовов
            // getApplicationIcon() = ~480 IPC в system_server, а перегрузка
            // system_server — это его watchdog-кил и перезагрузка телефона
            // (см. Throttle). Плюс работа сериализована и отсекается поколением.
            if (gen != appListGen || !running) return@post
            val apps = try { AppCatalog.filter(AppCatalog.load(ctx), query) } catch (e: Exception) { emptyList() }
            if (gen != appListGen || !running) return@post
            val shown = apps.take(60)
            for (a in shown) {
                if (gen != appListGen || !running) return@post
                if (!appIconCache.containsKey(a.pkg)) {
                    appIconCache[a.pkg] = AppCatalog.icon(ctx, a)
                }
            }
            if (gen != appListGen || !running) return@post
            val icons = HashMap<String, android.graphics.drawable.Drawable?>(shown.size)
            for (a in shown) icons[a.pkg] = appIconCache[a.pkg]
            ui.post {
                // Пока грузились, пользователь мог напечатать ещё символ или
                // закрыть панель — такой результат больше неактуален.
                if (gen != appListGen || appListBox == null) return@post
                renderAppList(apps, shown, icons)
            }
        }
    }

