private fun fillAppList(query: String?) {
        val box = appListBox ?: return
        val gen = ++appListGen
        box.removeAllViews()
        box.addView(TextView(this).apply {
            text = "Загрузка списка приложений…"
            textSize = 13f
            setTextColor(txtSub)
            setPadding(dp(6), dp(12), dp(6), dp(12))
        })
        val ctx = applicationContext
        Thread {
            // Список пакетов (~300) и иконки (по одному binder-вызову на
            // приложение) — это сотни IPC в UI-потоке, т.е. ANR. Раньше всё
            // это выполнялось синхронно на каждый символ поисковой строки.
            if (!running) return@Thread
            val apps = try { AppCatalog.filter(AppCatalog.load(ctx), query) } catch (e: Exception) { emptyList() }
            if (!running) return@Thread
            val shown = apps.take(60)
            val icons = HashMap<String, android.graphics.drawable.Drawable?>(shown.size)
            for (a in shown) {
                if (!running) return@Thread
                icons[a.pkg] = AppCatalog.icon(ctx, a)
            }
            ui.post {
                // Пока грузились, пользователь мог напечатать ещё символ или
                // закрыть панель — такой результат больше неактуален.
                if (gen != appListGen || appListBox == null) return@post
                renderAppList(apps, shown, icons)
            }
        }.start()
    }

