package app.yomikaioverlay.ot


import android.graphics.Bitmap
import android.util.Base64
import org.json.JSONArray
import org.json.JSONObject
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL

/**
 * Minimal LLM-vision client. Three endpoints: Zen Vision (free, no key),
 * OpenRouter (user key), Google AI / Gemini Vision (user key). Also has
 * non-vision helpers: Zen translation, OpenRouter translation, Gemini
 * translation, and detectSpeaker() for automatic voice selection.
 *
 * Важно: OpenAI-совместимые endpoint'ы отвечают форматом
 * `choices[0].message.content`, а Gemini — `candidates[0].content.parts[0].text`.
 * Раньше оба разбирались только как chat-completions, из-за чего все
 * Gemini-маршруты (перевод и vision) молча возвращали null.
 */
object LlmClient {
    /** Максимальная сторона картинки для vision-запроса (больше — впустую трафик). */
    internal const val MAX_VISION_SIDE = 1024

    /** Не читать ответ сервера целиком: защита от бесконечного потока/OOM. */
    internal const val MAX_RESPONSE_BYTES = 1 shl 20

    private val wsRe = Regex("\\s+")

    /** Бесплатные модели хаба (порядок = приоритет перебора). */
    val ZEN_FREE = listOf(
        "ling-3.1-flash-free",
        "nemotron-3.5-lightning-free",
        "mimo-v2.6-flash-free",
        "longcat-2.5-preview-free",
        "jev-1.13-free",
    )

    val GEMINI_FREE = listOf("gemini-2.5-flash", "gemini-2.5-pro", "gemini-2.0-flash")

    val OR_FREE = listOf(
        "google/gemini-2.0-flash-exp:free",
        "meta-llama/llama-3.2-11b-vision-instruct:free",
        "qwen/qwen2.5-vl-7b-instruct:free",
        "nvidia/nemotron-nano-12b-v2-vl:free",
        "google/gemini-2.5-flash",
    )

    /** Ответ LLM: текст + реально потраченные токены (0 если сервер не сказал). */
    data class ChatResult(val text: String, val totalTokens: Long)

    fun tokensFor(textOrHintWords: Int): Int {
        val n = textOrHintWords.coerceAtLeast(1)
        return (n * 4 + 48).coerceIn(64, 220)
    }

    fun visionOcr(bmp: Bitmap, model: String, russianOnly: Boolean, scanMode: String): String? =
        visionFull(bmp, model, russianOnly, scanMode)?.text

    fun visionFull(bmp: Bitmap, model: String, russianOnly: Boolean, scanMode: String): ChatResult? =
        postChatFull(
            "https://opencode.ai/zen/v1/chat/completions", null,
            visionBody(model, bmp, ocrPrompt(russianOnly, scanMode), tokensFor(guessWords(bmp)), MAX_VISION_SIDE),
        )

    fun visionOpenRouter(bmp: Bitmap, key: String, model: String, russianOnly: Boolean): String? {
        if (key.isBlank()) return null
        return postChatFull(
            "https://openrouter.ai/api/v1/chat/completions", "Bearer $key",
            visionBody(model, bmp, ocrPrompt(russianOnly, "rect"), tokensFor(guessWords(bmp)), MAX_VISION_SIDE),
        )?.text
    }

    fun visionGemini(ctx: android.content.Context, bmp: Bitmap, russianOnly: Boolean, scanMode: String): String? {
        val key = EnginePrefs.googleApiKey(ctx)
        if (key.isBlank()) return null
        val model = EnginePrefs.googleModel(ctx).ifBlank { GEMINI_FREE.first() }
        val base64 = toJpegB64(bmp, MAX_VISION_SIDE)
        val body = JSONObject().apply {
            put("contents", JSONArray().put(JSONObject().apply {
                put("parts", JSONArray().apply {
                    put(JSONObject().put("text", ocrPrompt(russianOnly, scanMode)))
                    put(JSONObject().put("inline_data", JSONObject().apply {
                        // toJpegB64 отдаёт JPEG — подпись обязана совпадать,
                        // иначе Gemini отвечает INVALID_ARGUMENT на картинку.
                        put("mime_type", "image/jpeg")
                        put("data", base64)
                    }))
                })
            }))
            put("generationConfig", JSONObject().put("temperature", 0.0))
        }
        return postChatFull(
            "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$key", null,
            body,
        )?.text
    }

    /** Промпт перевода под язык назначения: кириллица для RU, латиница для EN. */
    fun trPrompt(text: String, target: String): String = if (target == "en") {
        "Translate this line of a visual novel / game into natural ENGLISH.\n" +
            "Output ONLY the translation, in Latin letters. Keep names as-is.\n" +
            "No quotes, no notes.\n\nText:\n$text"
    } else {
        "Переведи реплику комикса на естественный русский.\n" +
            "Пиши ТОЛЬКО кириллицей. Не оставляй английских слов (кроме имён).\n" +
            "Без кавычек и пояснений.\n\nТекст:\n$text"
    }

    fun translateZen(text: String, model: String, target: String = "ru"): String? {
        val words = text.split(wsRe).size
        return chat(
            "https://opencode.ai/zen/v1/chat/completions", null,
            // setZenModel() в UI не вызывается, поэтому zenModel() всегда пуст.
            // Без фолбэка уходил запрос с "model": "" — хаб отвечал 4xx,
            // и весь Zen-маршрут был мёртвым.
            model.ifBlank { ZEN_FREE.first() },
            trPrompt(text, target), tokensFor(words),
        )
    }

    fun translateOpenRouter(text: String, key: String, model: String, target: String = "ru"): String? {
        if (key.isBlank()) return null
        if (model.isBlank()) return null
        val words = text.split(wsRe).size
        return chat(
            "https://openrouter.ai/api/v1/chat/completions", "Bearer $key", model,
            trPrompt(text, target), tokensFor(words),
        )
    }

    fun translateGemini(ctx: android.content.Context, text: String, target: String = "ru"): String? {
        val key = EnginePrefs.googleApiKey(ctx)
        if (key.isBlank()) return null
        val model = EnginePrefs.googleModel(ctx).ifBlank { GEMINI_FREE.first() }
        val prompt = if (target == "en") {
            "Translate into natural ENGLISH (Latin letters only). " +
                "No notes or quotes. Output only the translation:\n$text"
        } else {
            "Переведи на естественный русский язык (только кириллица, без латиницы). " +
                "Никаких пояснений или кавычек. Только перевод:\n$text"
        }
        val body = JSONObject().apply {
            put("contents", JSONArray().put(JSONObject().apply {
                put("parts", JSONArray().put(JSONObject().put("text", prompt)))
            }))
            put("generationConfig", JSONObject().put("temperature", 0.0))
        }
        return postJson(
            "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$key", null,
            body,
        )
    }

    /** Ask the LLM who speaks this dialogue (MALE/FEMALE/TEEN/NARRATOR). */
    fun detectSpeaker(ctx: android.content.Context, text: String): VoiceKind? {
        val key = EnginePrefs.googleApiKey(ctx)
        if (key.isBlank()) return null
        val model = EnginePrefs.googleModel(ctx).ifBlank { GEMINI_FREE.first() }
        val prompt = "Look at this short dialogue text and return the speaker's gender as a single word: " +
            "MALE, FEMALE, TEEN, or NARRATOR. Just the word, no explanation.\n\nText:\n$text"
        val body = JSONObject().apply {
            put("contents", JSONArray().put(JSONObject().apply {
                put("parts", JSONArray().put(JSONObject().put("text", prompt)))
            }))
            put("generationConfig", JSONObject().put("temperature", 0.0))
        }
        val raw = runCatching {
            val c = URL("https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$key")
                .openConnection() as HttpURLConnection
            c.requestMethod = "POST"
            c.doOutput = true
            c.connectTimeout = 8000
            c.readTimeout = 12000
            c.setRequestProperty("Content-Type", "application/json")
            c.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
            val out = if (c.responseCode in 200..299) c.inputStream.bufferedReader().readText() else ""
            c.disconnect()
            out
        }.getOrNull() ?: return null

        return runCatching {
            val word = JSONObject(raw).optJSONArray("candidates")?.optJSONObject(0)
                ?.optJSONObject("content")?.optJSONArray("parts")?.optJSONObject(0)?.optString("text", "")
                ?.trim()?.split(" ")?.firstOrNull()?.uppercase() ?: return@runCatching null
            when (word) {
                "MALE" -> VoiceKind.MALE
                "FEMALE" -> VoiceKind.FEMALE
                "TEEN" -> VoiceKind.TEEN
                else -> VoiceKind.OTHER
            }
        }.getOrNull()
    }

    fun postJson(endpoint: String, bearer: String?, body: JSONObject): String? =
        postChatFull(endpoint, bearer, body)?.text

    /**
     * POST json → [ChatResult]. Понимает оба формата ответа:
     * OpenAI-совместимый (`choices[0].message.content` + `usage.total_tokens`)
     * и Gemini (`candidates[0].content.parts[0].text` + `usageMetadata.totalTokenCount`).
     * Возвращает null при сетевой ошибке или пустом тексте.
     */
    fun postChatFull(endpoint: String, bearer: String?, body: JSONObject): ChatResult? {
        return runCatching {
            val c = URL(endpoint).openConnection() as HttpURLConnection
            c.requestMethod = "POST"
            c.doOutput = true
            c.connectTimeout = 15_000
            c.readTimeout = 35_000
            c.setRequestProperty("Content-Type", "application/json")
            c.setRequestProperty("HTTP-Referer", "https://github.com/sj0404-collab/overlay-translator")
            c.setRequestProperty("X-Title", "OverlayTranslator")
            if (!bearer.isNullOrBlank()) c.setRequestProperty("Authorization", bearer)
            val raw = try {
                c.outputStream.use { it.write(body.toString().toByteArray()) }
                val stream = if (c.responseCode in 200..299) c.inputStream else c.errorStream
                // Раньше читалось без ограничения и без use{}: на 4xx/5xx
                // getInputStream() бросает исключение, disconnect() не
                // доходил, и сокет навсегда оставался в keep-alive пуле.
                stream?.use { String(it.readNBytes(MAX_RESPONSE_BYTES), Charsets.UTF_8) }.orEmpty()
            } finally {
                c.disconnect()
            }
            if (raw.isBlank()) return@runCatching null
            val json = runCatching { JSONObject(raw) }.getOrNull() ?: return@runCatching null

            // OpenAI-совместимый формат.
            val choices = json.optJSONArray("choices")
            if (choices != null && choices.length() > 0) {
                val msg = choices.optJSONObject(0)
                    ?.optJSONObject("message")
                    ?.optString("content")
                val usage = json.optJSONObject("usage")
                val tokens = usage?.optLong("total_tokens", 0L) ?: 0L
                if (!msg.isNullOrBlank()) {
                    return@runCatching ChatResult(RuText.stripWrappers(msg), tokens)
                }
            }

            // Формат Gemini.
            val cands = json.optJSONArray("candidates")
            if (cands != null && cands.length() > 0) {
                val txt = cands.optJSONObject(0)
                    ?.optJSONObject("content")
                    ?.optJSONArray("parts")
                    ?.optJSONObject(0)
                    ?.optString("text")
                val tokens = json.optJSONObject("usageMetadata")
                    ?.optLong("totalTokenCount", 0L) ?: 0L
                if (!txt.isNullOrBlank()) {
                    return@runCatching ChatResult(RuText.stripWrappers(txt), tokens)
                }
            }
            null
        }.getOrNull()
    }

    /* ───────────────── helpers ───────────────── */

    private fun chat(endpoint: String, bearer: String?, model: String, prompt: String, maxTok: Int): String? {
        val body = JSONObject().put("model", model).put("max_tokens", maxTok)
            .put("messages", JSONArray().put(JSONObject().put("role", "user").put("content", prompt)))
        return postJson(endpoint, bearer, body)
    }

    /** Build a vision-call JSON body with intermediate variables (no paren counting). */
    private fun visionBody(model: String, bmp: Bitmap, prompt: String, maxTok: Int, maxSide: Int): JSONObject {
        val b64 = toJpegB64(bmp, maxSide)
        val userText = JSONObject().put("type", "text").put("text", prompt)
        val userImage = JSONObject().put("type", "image_url")
            .put("image_url", JSONObject().put("url", "data:image/jpeg;base64,$b64"))
        val content = JSONArray().put(userText).put(userImage)
        val userMessage = JSONObject().put("role", "user").put("content", content)
        val messages = JSONArray().put(userMessage)
        return JSONObject()
            .put("model", model)
            .put("max_tokens", maxTok)
            .put("messages", messages)
    }

    private fun ocrPrompt(russianOnly: Boolean, scanMode: String): String {
        val lang = if (russianOnly)
            "Текст ТОЛЬКО на русском (кириллица). Латиницу не пиши, кроме имён если они реально на экране."
        else "Any text visible in this image. English, Russian, Japanese, or any other language. Transcribe exactly as written."
        val modeHint = when (scanMode) {
            "bubble" -> "This is one speech bubble. Extract only the dialogue inside."
            "full" -> "Extract all readable dialogue, top to bottom."
            else -> "Extract all printed text in the selected area."
        }
        return "$modeHint $lang Output ONLY the raw text, keep line breaks and spaces between words. No comments."
    }

    private fun guessWords(bmp: Bitmap): Int {
        val area = bmp.width * bmp.height
        return (area / 14000).coerceIn(4, 40)
    }

    internal fun toJpegB64(bmp: Bitmap, maxSide: Int): String {
        val m = maxOf(bmp.width, bmp.height)
        val scaled = if (m > maxSide) {
            val s = maxSide.toFloat() / m
            Bitmap.createScaledBitmap(bmp,
                (bmp.width * s).toInt().coerceAtLeast(32),
                (bmp.height * s).toInt().coerceAtLeast(32), true)
        } else bmp
        try {
            val os = ByteArrayOutputStream()
            scaled.compress(Bitmap.CompressFormat.JPEG, 62, os)
            return Base64.encodeToString(os.toByteArray(), Base64.NO_WRAP)
        } finally {
            // Раньше уменьшенный битмап (4 МБ на 1024×1024) не освобождался:
            // Zen Free звал это 5 раз за скан — до 20 МБ утечки за цикл.
            if (scaled !== bmp) scaled.recycle()
        }
    }
}

/** Пол говорящего (для выбора голоса TTS) — как в overlay-translator. */
enum class VoiceKind { MALE, FEMALE, TEEN, NARRATOR, OTHER }

