package app.yomikaioverlay.ot

object RuText {
    // Регексы собираются один раз: clean() зовётся на каждом ответе LLM, и
    // Regex(String) не кэшируется — раньше паттерн пересобирался на каждой
    // строке ответа (для страницы манги это десятки компиляций за скан).
    private val fences = Regex("(?s)```[a-zA-Z]*\\s*(.*?)\\s*```")
    private val prefix = Regex("(?iu)^\\s*(here is|here's|the translation|translation|extracted|перевод)\\s*[:\\-]?\\s*")
    private val ws = Regex("\\s+")
    private val spaces = Regex("[ \\t]+")

    /**
     * Убирает только обвязку ответа LLM (markdown-заборы, «Here is: …»).
     *
     * Не трогает слова и не фильтрует по алфавиту — в отличие от [clean].
     * Нужен всем, кто получил текст на НЕИЗВЕСТНОМ языке: OCR с латиницей,
     * японским или кириллицей. Раньше эти ответы прогонялись через [clean],
     * который выкидывал каждое латинское слово длиннее 2 букв — английский
     * OCR возвращал пустую строку, а перевод в EN был нечитаемым.
     */
    fun stripWrappers(raw: String): String {
        var s = raw.trim()
        if (s.isEmpty()) return ""
        fences.find(s)?.let { s = it.groupValues[1].trim() }
        s = s.replace(prefix, "")
        s = s.replace(fences, "$1")
        var prev = ""
        while (prev != s) {
            prev = s
            s = s.replace(prefix, "").trim()
        }
        return spaces.replace(s, " ").trim()
    }

    /**
     * Чистка ответа, который должен быть на РУССКОМ: ё→е, выкидываем слова
     * с преобладанием латиницы (LLM периодически подмешивает английские
     * вставки), схлопываем пробелы и пустые строки.
     *
     * Применять ТОЛЬКО к русскому тексту — на латинице/иероглифах выкинет
     * почти всё (см. [stripWrappers]).
     */
    fun clean(raw: String): String {
        var s = stripWrappers(raw)
            .replace('ё', 'е')
            .replace('Ё', 'Е')
        val lines = s.split('\n').map { line ->
            val kept = line.split(ws).filter { w ->
                if (w.isEmpty()) false
                else {
                    val cyr = w.count { it in '\u0400'..'\u04FF' }
                    val lat = w.count { it in 'A'..'Z' || it in 'a'..'z' }
                    cyr >= lat || w.length <= 2
                }
            }
            kept.joinToString(" ")
        }.filter { it.isNotBlank() }
        return lines.joinToString("\n").replace(spaces, " ").trim()
    }

    fun preferRussianPrompt(): Boolean = true
}

