package app.yomikaioverlay.ot

import android.content.Context
import android.graphics.Bitmap
import android.os.SystemClock

/**
 * «Zen Free» — бесплатный ИИ-хаб: перебирает модели [LlmClient.ZEN_FREE]
 * и берёт первую, ответившую текстом. Ключ не нужен.
 *
 * Если хаб недоступен (403/сеть/пустой ответ) — молча падаем на Google Lens,
 * который тоже бесключевой: пользователь всегда получает результат скана,
 * а не пустой экран.
 */
class ZenFreeOcrEngine(private val ctx: Context) : OcrEngine {

    private val fallbackGlens by lazy { GlensOcrEngine() }

    override fun recognizeText(image: Bitmap): String {
        // Перебор 5 моделей без общего дедлайна занимал до 250 с (connect+read
        // на модель) плюс фолбэк Lens — до 5 минут, в течение которых
        // scanInFlight=true и все следующие сканы отбрасывались. Плюс
        // HandlerThread нельзя прервать из onDestroy, пока он в сети.
        val deadline = SystemClock.elapsedRealtime() + BUDGET_MS
        for (model in LlmClient.ZEN_FREE) {
            if (Thread.interrupted() || SystemClock.elapsedRealtime() >= deadline) break
            try {
                val result = LlmClient.visionFull(
                    image, model, russianOnly = false, scanMode = "rect",
                )
                if (result != null && result.text.isNotBlank()) {
                    if (result.totalTokens > 0) {
                        EnginePrefs.incrementTokens(ctx, result.totalTokens)
                    }
                    return result.text
                }
            } catch (e: Exception) {
                // следующая модель
            }
        }
        if (Thread.interrupted()) return ""
        val lens = try { fallbackGlens.recognizeText(image) } catch (e: Exception) { "" }
        if (lens.isNotBlank()) {
            EnginePrefs.incrementTokens(ctx, (lens.length * 1.5f).toLong().coerceAtLeast(15L))
        }
        return lens
    }

    override fun close() {
        fallbackGlens.close()
    }

    private companion object {
        /** Общий бюджет на перебор моделей: ~2 ответа, дальше — фолбэк Lens. */
        const val BUDGET_MS = 25_000L
    }
}

package app.yomikaioverlay.ot

import android.graphics.Bitmap
import android.graphics.Rect
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.text.TextRecognition
import com.google.mlkit.vision.text.TextRecognizer
import com.google.mlkit.vision.text.latin.TextRecognizerOptions
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit

data class LayoutBlock(val text: String, val rect: Rect)

/**
 * Разметка + признак владения битмапом.
 *
 * [bitmapInUse] == true означает, что ML Kit ещё держит битмап (таймаут или
 * прерывание) и вызывающая сторона ОБЯЗАНА его не трогать. Раньше в этом
 * случае вызывающий делал recycle() — нативный use-after-free.
 *
 * Дженерик, потому что наружу отдаётся то, что просил вызывающий: сырые
 * [LayoutBlock] или уже [android.graphics.Rect] в порядке чтения.
 */
class LayoutResult<T>(val blocks: List<T>, val bitmapInUse: Boolean)

/**
 * Гибридная пометка: ML Kit даёт координаты блоков текста (рамки + номера +
 * порядок чтения), а сам распознанный текст для озвучки/перевода остаётся
 * онлайн (Lens/Zen) — поэтому покоординатная часть может жить на устройстве.
 *
 * Если Play Services / ML-модель недоступны — [isAvailable] == false и оверлей
 * работает как раньше, без рамок и номеров.
 */
class LayoutOcr {
    @Volatile
    private var recognizer: TextRecognizer? = createClient()

    val isAvailable: Boolean get() = recognizer != null

    /** Синхронно (worker-поток): блоки с координатами в пикселях битмапа. */
    fun blocks(bitmap: Bitmap): LayoutResult<LayoutBlock> {
        val rec = recognizer ?: return LayoutResult(emptyList<LayoutBlock>(), bitmapInUse = false)
        val latch = CountDownLatch(1)
        var result: com.google.mlkit.vision.text.Text? = null
        var failed = false
        try {
            val task = rec.process(InputImage.fromBitmap(bitmap, 0))
            task.addOnSuccessListener { r -> result = r; latch.countDown() }
            task.addOnFailureListener { _ -> failed = true; latch.countDown() }
        } catch (e: Throwable) {
            failed = true
            latch.countDown()
        }
        // Таймаут НЕ означает, что ML Kit отпустил битмап: задача всё ещё
        // летит в нативный код. Возвращать управление значило отдать вызывающей
        // стороне право recycle() — это use-after-free в нативе. Поэтому при
        // таймауте битмап намеренно оставляем живым и просто отдаём пусто.
        val done = try { latch.await(TIMEOUT_MS, TimeUnit.SECONDS) } catch (e: InterruptedException) { false }
        if (!done) return LayoutResult(emptyList<LayoutBlock>(), bitmapInUse = true)
        if (failed || result == null) {
            // recognizer без close() утекает нативный клиент GMS.
            runCatching { rec.close() }
            if (recognizer === rec) recognizer = null
            return LayoutResult(emptyList<LayoutBlock>(), bitmapInUse = false)
        }
        // Строчный уровень: рамки точнее и складываются в колонки текста,
        // тогда как блочный уровень даёт крупные «разбросанные» прямоугольники.
        val lines = result.textBlocks
            .flatMap { it.lines }
            .mapNotNull { ln ->
                val box = ln.boundingBox ?: return@mapNotNull null
                if (ln.text.isBlank()) return@mapNotNull null
                LayoutBlock(ln.text, box)
            }
        // Задача завершилась — нативная сторона битмап больше не читает.
        return LayoutResult(lines, bitmapInUse = false)
    }

    fun close() {
        val rec = recognizer
        recognizer = null
        try { rec?.close() } catch (e: Throwable) { }
    }

    private companion object {
        const val TIMEOUT_MS = 15L
        fun createClient(): TextRecognizer? = try {
            TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)
        } catch (e: Throwable) {
            null
        }
    }
}

