                val x1 = b.right.toFloat() + pad
                val y1 = b.bottom.toFloat() + pad + boxShiftY
                c.drawRoundRect(x0, y0, x1, y1, corner, corner, if (active) bubbleFillActive else bubbleFill)
                // хвостик облачка снизу по центру
                val bx = (x0 + x1) / 2f
                tailPath.reset()
