    /** Диалог со списком приложений устройства: поиск и запуск в один тап. */
    private fun showApps() {
        // AppCatalog.load() и AppCatalog.icon() — тяжёлые вызовы: список ~300
        // пакетов плюс по одному binder-вызову на ярлык и на иконку. Раньше всё
        // это выполнялось на UI-потоке (до показа диалога и на каждый символ
