package app.yomikaioverlay.ot

import android.graphics.Bitmap
import android.util.Log
import java.io.ByteArrayOutputStream
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL
import kotlin.random.Random

/**
 * Google Lens OCR via protobuf endpoint.
 * Ported from Yomihon's GlensOcrEngine.
 *
 * Falls back gracefully: returns empty string on any error so that
 * [OcrRouter] can try the next engine.
 */
class GlensOcrEngine : OcrEngine {

    override fun recognizeText(image: Bitmap): String {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val maxDim = maxOf(image.width, image.height)
        val resized = if (maxDim > MAX_IMAGE_DIMENSION) {
            val s = MAX_IMAGE_DIMENSION.toFloat() / maxDim.toFloat()
            Bitmap.createScaledBitmap(image, 
                (image.width * s).toInt().coerceAtLeast(1),
                (image.height * s).toInt().coerceAtLeast(1),
                true,
            )
        } else null
        val working = resized ?: image
        return try {
            val encoded = ByteArrayOutputStream()
            if (!working.compress(Bitmap.CompressFormat.PNG, 100, encoded))
                throw IOException("PNG encode failed")
            val payload = buildRequestPayload(encoded.toByteArray(), working.width, working.height)
            val resp = executeRequest(payload)
            extractText(resp)
        } catch (e: Exception) {
            Log.w(TAG, "Glens failed, returning empty", e)
            ""
        } finally {
            resized?.recycle()
        }
    }

    /* ─────────── Request ─────────── */

    internal fun buildRequestPayload(pngBytes: ByteArray, w: Int, h: Int): ByteArray {
        // Must be non-negative for uint64 varint encoding
        val requestId = Random.nextLong().toLong() and Long.MAX_VALUE
        return ProtoWriter().apply {
            writeMessage(1) { objReq ->
                // objects_request_context
                objReq.writeMessage(1) { ctx ->
                    // request_id
                    ctx.writeMessage(3) { rid ->
                        rid.writeUInt64(1, requestId)
                        rid.writeInt32(2, 0)
                        rid.writeInt32(3, 0)
                        rid.writeBytes(4, Random.nextBytes(16))
                    }
                    // client_context
                    ctx.writeMessage(4) { cc ->
                        cc.writeInt32(1, PLATFORM_WEB)
                        cc.writeInt32(2, SURFACE_CHROMIUM)
                        cc.writeMessage(4) { lc ->
                            lc.writeString(1, DEFAULT_CLIENT_LANGUAGE)
                            lc.writeString(2, DEFAULT_CLIENT_REGION)
                        }
                        cc.writeMessage(7) { filters ->
                            filters.writeMessage(1) { fl ->
                                fl.writeInt32(1, AUTO_FILTER)
                            }
                        }
                    }
                }
                // image_data
                objReq.writeMessage(3) { img ->
                    img.writeMessage(1) { p ->
                        p.writeBytes(1, pngBytes)
                    }
                    img.writeMessage(3) { m ->
                        m.writeInt32(1, w)
                        m.writeInt32(2, h)
                    }
                }
            }
        }.toByteArray()
    }

    /* ─────────── HTTP ─────────── */

    private fun executeRequest(payload: ByteArray): ByteArray {
        val conn = (URL(LENS_ENDPOINT).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 10_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/x-protobuf")
            setRequestProperty("User-Agent", DEFAULT_USER_AGENT)
            setRequestProperty("X-Goog-Api-Key", API_KEY)
        }
        return try {
            conn.outputStream.use { it.write(payload) }
            val status = conn.responseCode
            val bytes = (if (status in 200..299) conn.inputStream else conn.errorStream)
                ?.use { it.readBytes() } ?: ByteArray(0)
            if (status !in 200..299)
                throw IOException("HTTP $status: ${bytes.toString(Charsets.UTF_8).take(200)}")
            bytes
        } finally {
            conn.disconnect()
        }
    }

    /* ─────────── Response parser ─────────── */

    private fun extractText(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val allLines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3
            val wire = tag and 0x7
            if (field == 2 && wire == 2) {
                allLines += parseObjectsResponse(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return allLines.joinToString("\n").trim()
    }

    private fun parseObjectsResponse(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 3 && wire == 2) lines += parseText(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseText(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val result = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) result += parseTextLayout(reader.readBytes())
            else reader.skipField(wire)
        }
        return result
    }

    private fun parseTextLayout(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) lines += parseParagraph(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseParagraph(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 2 && wire == 2) lines += parseLine(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    /** A "line" is a sequence of words; each word carries its own trailing separator. */
    private fun parseLine(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val sb = StringBuilder()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) {
                sb.append(parseWord(reader.readBytes()))
            } else {
                reader.skipField(wire)
            }
        }
        return sb.toString()
    }

    /** Returns text + separator (e.g. "Hello" + " "). */
    private fun parseWord(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        var text = ""
        var separator = ""
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            when {
                field == 2 && wire == 2 -> text = reader.readString()
                field == 3 && wire == 2 -> separator = reader.readString()
                else -> reader.skipField(wire)
            }
        }
        return text + separator
    }

    override fun close() {}

    companion object {
        private const val TAG = "Glens"
        private const val LENS_ENDPOINT = "https://lensfrontend-pa.googleapis.com/v1/crupload"
        private const val API_KEY = "AIzaSyDr2UxVnv_U85AbhhY8XSHSIavUW0DC-sY"
        private val DEFAULT_USER_AGENT =
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36"
        private const val DEFAULT_CLIENT_LANGUAGE = "ru"
        private const val DEFAULT_CLIENT_REGION = "Europe/Moscow"
        private const val MAX_IMAGE_DIMENSION = 1500
        private const val PLATFORM_WEB = 3
        private const val SURFACE_CHROMIUM = 4
        private const val AUTO_FILTER = 1
    }
}

/* ────────────────────────────────────────────────
 *  Minimal protobuf reader / writer — no deps
 * ──────────────────────────────────────────────── */

internal class ProtoReader(private val bytes: ByteArray) {
    private var pos = 0

    fun hasRemaining() = pos < bytes.size

    fun readTag(): Int? = if (hasRemaining()) readVarint32() else null

    fun readBytes(): ByteArray {
        val len = readVarint32() ?: return ByteArray(0)
        val safeLen = len.coerceAtMost(bytes.size - pos)
        val result = bytes.copyOfRange(pos, pos + safeLen)
        pos += safeLen
        return result
    }

    fun readString(): String = readBytes().toString(Charsets.UTF_8)

    fun skipField(wireType: Int) {
        when (wireType) {
            0 -> readVarint32()
            1 -> { pos += 8; if (pos > bytes.size) pos = bytes.size }
            2 -> { val len = readVarint32() ?: 0; pos += len.coerceAtMost(bytes.size - pos); if (pos > bytes.size) pos = bytes.size }
            5 -> { pos += 4; if (pos > bytes.size) pos = bytes.size }
        }
    }

    internal fun readVarint32(): Int? {
        var result = 0L
        var shift = 0
        while (shift < 64) {
            if (!hasRemaining()) return null
            val b = bytes[pos++].toLong() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80L) == 0L) return result.toInt()
            shift += 7
        }
        return result.toInt()
    }

    /** Полный 64-битный varint: длинные значения (uint64) больше не рвут поток. */
    internal fun readVarint64(): Long? {
        var result = 0L
        var shift = 0
        while (shift < 64) {
            if (!hasRemaining()) return null
            val b = bytes[pos++].toLong() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80L) == 0L) return result
            shift += 7
        }
        return result
    }
}

internal class ProtoWriter {
    private val out = ByteArrayOutputStream()

    fun writeInt32(fieldNumber: Int, value: Int) {
        writeTag(fieldNumber, 0); writeVarint32(value)
    }

    fun writeUInt64(fieldNumber: Int, value: Long) {
        writeTag(fieldNumber, 0); writeVarint64(value)
    }

    fun writeString(fieldNumber: Int, value: String) {
        writeBytes(fieldNumber, value.toByteArray(Charsets.UTF_8))
    }

    fun writeBytes(fieldNumber: Int, value: ByteArray) {
        writeTag(fieldNumber, 2); writeVarint32(value.size); out.write(value)
    }

    fun writeMessage(fieldNumber: Int, block: (ProtoWriter) -> Unit) {
        val inner = ProtoWriter().also(block).toByteArray()
        writeBytes(fieldNumber, inner)
    }

    fun toByteArray(): ByteArray = out.toByteArray()

    private fun writeTag(field: Int, wire: Int) = writeVarint32((field shl 3) or wire)

    private fun writeVarint32(value: Int) {
        var v = value
        while ((v and 0x7F.inv()) != 0) { out.write((v and 0x7F) or 0x80); v = v ushr 7 }
        out.write(v and 0x7F)
    }

    private fun writeVarint64(value: Long) {
        var v = value
        // маска ~0x7F (а не ~0x80): иначе в поток уходил лишний нулевой байт
        // и varint переставал быть каноническим.
        while ((v and 0x7FL.inv()) != 0L) { out.write(((v and 0x7F) or 0x80).toInt()); v = v ushr 7 }
        out.write((v and 0x7F).toInt())
    }
}

package app.yomikaioverlay.ot

import app.yomikaioverlay.ot.ReadingOrder.TextBox
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Регрессия на разбивку ReadingOrder на полосы: полоса строится по
 * НАКОПЛЕННЫМ границам, а не по её первому элементу.
 *
 * Старая проверка `overlap(members.first(), r)` рвала одну строку надвое,
 * как только очередной блок переставал пересекаться с якорем, но всё ещё
 * пересекался с хвостом полосы.
 *
 * Порог 0.4 считается от КОРОТКОГО блока: inter / min(длина полосы, длина блока).
 */
class ReadingOrderBandTest {

    private fun keys(rects: List<TextBox>) =
        rects.map { "${it.left},${it.top},${it.right},${it.bottom}" }

    @Test
    fun `строка не рвётся на части`() {
        // a(0..100) и b(60..160) пересекаются на 40 из 100 → одна полоса,
        // её границы вырастают до 0..160. Но c(120..220) с якорем a(0..100)
        // не пересекается вовсе — проверка только по members.first() рвала бы
        // строку надвое ровно здесь.
        val a = TextBox(0, 0, 100, 100)
        val b = TextBox(0, 60, 100, 160)
        val c = TextBox(0, 120, 100, 220)
        val rows = ReadingOrder.rows(listOf(a, b, c))
        assertEquals("блоки a,b,c должны попасть в одну полосу", 1, rows.size)
        assertEquals(keys(listOf(a, b, c)), keys(rows[0]))
    }

    @Test
    fun `далеко отстоящие блоки остаются разными строками`() {
        val a = TextBox(0, 0, 100, 40)
        val b = TextBox(0, 400, 100, 440)
        assertEquals(2, ReadingOrder.rows(listOf(a, b)).size)
    }

    @Test
    fun `порог 0_4 перекрытия отсчитывается от короткого блока`() {
        // 20 из 40 = 0.5 → одна полоса.
        assertEquals(
            1,
            ReadingOrder.rows(listOf(TextBox(0, 0, 100, 40), TextBox(0, 20, 100, 60))).size,
        )
        // 10 из 40 = 0.25 → две полосы.
        assertEquals(
            2,
            ReadingOrder.rows(listOf(TextBox(0, 0, 100, 40), TextBox(0, 30, 100, 70))).size,
        )
    }

    @Test
    fun `колонки строятся по горизонтали и не сливаются`() {
        val left = TextBox(0, 0, 50, 400)
        val right = TextBox(300, 0, 350, 400)
        assertEquals(2, ReadingOrder.columns(listOf(left, right)).size)
    }

    @Test
    fun `колонка растёт вправо и не рвётся`() {
        val a = TextBox(0, 0, 200, 100)
        val b = TextBox(120, 0, 320, 100)
        val c = TextBox(240, 0, 440, 100)
        val cols = ReadingOrder.columns(listOf(a, b, c))
        assertEquals(1, cols.size)
        assertEquals(keys(listOf(a, b, c)), keys(cols[0]))
    }

    @Test
    fun `пустой и одиночный ввод`() {
        assertEquals(0, ReadingOrder.rows(emptyList()).size)
        val one = TextBox(1, 1, 2, 2)
        assertEquals(1, ReadingOrder.rows(listOf(one)).size)
        assertEquals(0, ReadingOrder.columns(emptyList()).size)
    }

    @Test
    fun `порядок входа не влияет на разбивку`() {
        val a = TextBox(0, 0, 100, 100)
        val b = TextBox(0, 60, 100, 160)
        val c = TextBox(0, 120, 100, 220)
        val d = TextBox(0, 500, 100, 600)
        assertEquals(
            keys(ReadingOrder.rows(listOf(a, b, c, d)).flatten()),
            keys(ReadingOrder.rows(listOf(d, c, b, a)).flatten()),
        )
    }

    @Test
    fun `ltr по сгруппированной строке идёт слева направо`() {
        val left = TextBox(0, 0, 40, 40)
        val right = TextBox(60, 10, 100, 50)
        assertEquals(
            keys(listOf(left, right)),
            keys(ReadingOrder.order(listOf(right, left), ReadingOrder.LTR)),
        )
    }
}

package app.yomikaioverlay.ot

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Регрессии на [RuText.stripWrappers] — чистку, которую применяют к ответам
 * LLM на НЕИЗВЕСТНОМ языке (OCR с латиницей/японским, перевод в EN).
 *
 * Раньше postChatFull прогонял через [RuText.clean] вообще всё, и
 * `clean("Hello world")` возвращал пустую строку: английский OCR не работал
 * ни в одном движке, а перевод RU→EN вычищался до ничего.
 */
class RuTextWrappersTest {

    @Test
    fun `латиница не вычищается`() {
        assertEquals("Hello world", RuText.stripWrappers("Hello world"))
    }

    @Test
    fun `смешанный текст с кириллицей сохраняется целиком`() {
        assertEquals("Привет Hello мир", RuText.stripWrappers("Привет Hello мир"))
    }

    @Test
    fun `японский иероглифы не трогаются`() {
        assertEquals("こんにちは世界", RuText.stripWrappers("こんにちは世界"))
    }

    @Test
    fun `длинное английское предложение не обрезается`() {
        val text = "The door creaks open and the wind howls outside"
        assertEquals(text, RuText.stripWrappers(text))
    }

    @Test
    fun `снимает приписки LLM`() {
        assertEquals("Открыта дверь", RuText.stripWrappers("Here is: Открыта дверь"))
        assertEquals("Открыта дверь", RuText.stripWrappers("Перевод: Открыта дверь"))
    }

    @Test
    fun `снимает приписки подряд`() {
        assertEquals("Open the door", RuText.stripWrappers("Here is the translation: Open the door"))
    }

    @Test
    fun `разбирает markdown-забор`() {
        assertEquals("Open the door", RuText.stripWrappers("```\nOpen the door\n```"))
        assertEquals("Open the door", RuText.stripWrappers("```text\nOpen the door\n```"))
    }

    @Test
    fun `не трогает ё — это не русская чистка`() {
        // clean() делает ё→е, stripWrappers() не должен: OCR обязан вернуть
        // текст как на экране.
        assertEquals("Ёлка", RuText.stripWrappers("Ёлка"))
    }

    @Test
    fun `пустой ввод`() {
        assertEquals("", RuText.stripWrappers(""))
        assertEquals("", RuText.stripWrappers("   \n  "))
    }

    @Test
    fun `clean по-прежнему чистит русский — включая ё→е и заборы`() {
        assertEquals("Елка", RuText.clean("```\nЁлка\n```"))
    }

    @Test
    fun `clean по-прежнему выкидывает латиницу из русской строки`() {
        val out = RuText.clean("Привет мир Hello world")
        assertFalse(out.contains("Hello"))
        assertTrue(out.contains("Привет"))
    }
}

