package app.yomikaioverlay.ot

import android.content.Context
import android.graphics.Bitmap
import org.json.JSONArray
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL

/**
 * Google AI (Gemini Vision) OCR engine, ported from Yomihon's reader build.
 * Requires a user-provided API key stored in [EnginePrefs.googleApiKey].
 */
class GoogleAiOcrEngine(private val ctx: Context) : OcrEngine {

    override fun recognizeText(image: Bitmap): String {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val apiKey = EnginePrefs.googleApiKey(ctx)
        if (apiKey.isBlank()) throw IllegalStateException("Google AI API key not set")
        val model = EnginePrefs.googleModel(ctx).ifBlank { "gemini-2.5-flash" }
        val base64 = LlmClient.toJpegB64(image, LlmClient.MAX_VISION_SIDE)

        val jsonBody = JSONObject().apply {
            put("generationConfig", JSONObject().put("temperature", 0.0))
            val contents = JSONArray()
            val item = JSONObject()
            val parts = JSONArray()
            parts.put(JSONObject().apply {
                put("text", "Perform STRICT OPTICAL CHARACTER RECOGNITION (OCR) ONLY. " +
                    "Transcribe the exact characters seen in this image verbatim. " +
                    "Do not hallucinate, do not translate, do not add any markdown formatting or commentary.")
            })
            parts.put(JSONObject().apply {
                put("inline_data", JSONObject().apply {
                    put("mime_type", "image/jpeg")
                    put("data", base64)
                })
            })
            item.put("parts", parts)
            contents.put(item)
            put("contents", contents)
        }

        val urlString = "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$apiKey"
        val connection = (URL(urlString).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 15_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/json")
        }
        return try {
            connection.outputStream.use { it.write(jsonBody.toString().toByteArray(Charsets.UTF_8)) }
            val status = connection.responseCode
            val text = (if (status in 200..299) connection.inputStream else connection.errorStream)
                ?.use { String(it.readNBytes(LlmClient.MAX_RESPONSE_BYTES), Charsets.UTF_8) } ?: ""
            if (status !in 200..299) throw RuntimeException("Gemini Vision failed HTTP $status: ${text.take(200)}")
            val resp = JSONObject(text)
            val candidates = resp.optJSONArray("candidates")
            val extracted = if (candidates != null && candidates.length() > 0) {
                val partsArr = candidates.getJSONObject(0).optJSONObject("content")
                    ?.optJSONArray("parts")
                if (partsArr != null && partsArr.length() > 0) {
                    partsArr.getJSONObject(0).optString("text", "")
                } else ""
            } else ""
            val totalTokens = resp.optJSONObject("usageMetadata")
                ?.optLong("totalTokenCount", 0L) ?: 0L
            EnginePrefs.incrementTokens(ctx, totalTokens)
            extracted.trim()
        } finally {
            connection.disconnect()
        }
    }

}

package app.yomikaioverlay.ot

import android.content.Context
import android.graphics.Bitmap
import org.json.JSONArray
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL

/**
 * Vision OCR routed through OpenRouter. Uses a user-supplied API key from
 * [EnginePrefs.openrouterKey] and a model picked in [EnginePrefs.orModel].
 * Defaults align with Yomihon's reader build (`google/gemini-2.5-flash`).
 */
class OpenRouterOcrEngine(private val ctx: Context) : OcrEngine {

    override fun recognizeText(image: Bitmap): String {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val key = EnginePrefs.openrouterKey(ctx)
        if (key.isBlank()) throw IllegalStateException("OpenRouter API key is empty")
        val model = EnginePrefs.orModel(ctx).ifBlank { "google/gemini-2.5-flash" }
        val base64 = LlmClient.toJpegB64(image, LlmClient.MAX_VISION_SIDE)

        val json = JSONObject().apply {
            put("model", model)
            put("temperature", 0.0)
            val msgs = JSONArray()
            val userMsg = JSONObject()
            userMsg.put("role", "user")
            val content = JSONArray()
            content.put(JSONObject().apply {
                put("type", "text")
                put("text", "Perform STRICT OPTICAL CHARACTER RECOGNITION (OCR) ONLY. " +
                    "Transcribe the exact text from the image verbatim without translating, " +
                    "explaining, summarizing, or adding any commentary. If no text is visible, " +
                    "return empty string.")
            })
            content.put(JSONObject().apply {
                put("type", "image_url")
                put("image_url", JSONObject().apply {
                    put("url", "data:image/jpeg;base64,$base64")
                })
            })
            userMsg.put("content", content)
            msgs.put(userMsg)
            put("messages", msgs)
        }

        val connection = (URL(ENDPOINT).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 15_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/json")
            setRequestProperty("Authorization", "Bearer $key")
            setRequestProperty("HTTP-Referer", "https://github.com/sj0404-collab/overlay-translator")
            setRequestProperty("X-Title", "OverlayTranslator")
        }
        return try {
            connection.outputStream.use { it.write(json.toString().toByteArray(Charsets.UTF_8)) }
            val status = connection.responseCode
            val body = (if (status in 200..299) connection.inputStream else connection.errorStream)
                ?.use { String(it.readNBytes(LlmClient.MAX_RESPONSE_BYTES), Charsets.UTF_8) } ?: ""
            if (status !in 200..299) throw RuntimeException("OpenRouter failed HTTP $status: ${body.take(200)}")
            val resp = JSONObject(body)
            val choices = resp.optJSONArray("choices")
            val extracted = if (choices != null && choices.length() > 0) {
                choices.getJSONObject(0).optJSONObject("message")?.optString("content", "") ?: ""
            } else ""
            val tokens = resp.optJSONObject("usage")?.optLong("total_tokens", 0L) ?: 0L
            EnginePrefs.incrementTokens(ctx, tokens)
            extracted.trim()
        } finally {
            connection.disconnect()
        }
    }

    companion object {
        private const val ENDPOINT = "https://openrouter.ai/api/v1/chat/completions"
    }
}

