 * translation, and detectSpeaker() for automatic voice selection.
 *
 * Важно: OpenAI-совместимые endpoint'ы отвечают форматом
 * `choices[0].message.content`, а Gemini — `candidates[0].content.parts[0].text`.
 * Раньше оба разбирались только как chat-completions, из-за чего все
 * Gemini-маршруты (перевод и vision) молча возвращали null.
 */
object LlmClient {
    /** Максимальная сторона картинки для vision-запроса (больше — впустую трафик). */
    private const val MAX_VISION_SIDE = 1024

    /** Бесплатные модели хаба (порядок = приоритет перебора). */
    val ZEN_FREE = listOf(
        "ling-3.1-flash-free",
        "nemotron-3.5-lightning-free",
        "mimo-v2.6-flash-free",
        "longcat-2.5-preview-free",
        "jev-1.13-free",
    )

    val GEMINI_FREE = listOf("gemini-2.5-flash", "gemini-2.5-pro", "gemini-2.0-flash")

    val OR_FREE = listOf(
        "google/gemini-2.0-flash-exp:free",
        "meta-llama/llama-3.2-11b-vision-instruct:free",
        "qwen/qwen2.5-vl-7b-instruct:free",
        "nvidia/nemotron-nano-12b-v2-vl:free",
        "google/gemini-2.5-flash",
    )

    /** Ответ LLM: текст + реально потраченные токены (0 если сервер не сказал). */
    data class ChatResult(val text: String, val totalTokens: Long)

    fun tokensFor(textOrHintWords: Int): Int {
        val n = textOrHintWords.coerceAtLeast(1)
        return (n * 4 + 48).coerceIn(64, 220)
    }

    fun visionOcr(bmp: Bitmap, model: String, russianOnly: Boolean, scanMode: String): String? =
        visionFull(bmp, model, russianOnly, scanMode)?.text

    fun visionFull(bmp: Bitmap, model: String, russianOnly: Boolean, scanMode: String): ChatResult? =
        postChatFull(
            "https://opencode.ai/zen/v1/chat/completions", null,
            visionBody(model, bmp, ocrPrompt(russianOnly, scanMode), tokensFor(guessWords(bmp)), MAX_VISION_SIDE),
        )

    fun visionOpenRouter(bmp: Bitmap, key: String, model: String, russianOnly: Boolean): String? {
        if (key.isBlank()) return null
        return postChatFull(
            "https://openrouter.ai/api/v1/chat/completions", "Bearer $key",
            visionBody(model, bmp, ocrPrompt(russianOnly, "rect"), tokensFor(guessWords(bmp)), MAX_VISION_SIDE),
        )?.text
    }

    fun visionGemini(ctx: android.content.Context, bmp: Bitmap, russianOnly: Boolean, scanMode: String): String? {
        val key = EnginePrefs.googleApiKey(ctx)
        if (key.isBlank()) return null
        val model = EnginePrefs.googleModel(ctx).ifBlank { GEMINI_FREE.first() }
        val base64 = toJpegB64(bmp, MAX_VISION_SIDE)
        val body = JSONObject().apply {
            put("contents", JSONArray().put(JSONObject().apply {
                put("parts", JSONArray().apply {
                    put(JSONObject().put("text", ocrPrompt(russianOnly, scanMode)))
                    put(JSONObject().put("inline_data", JSONObject().apply {
                        put("mime_type", "image/png")
                        put("data", base64)
                    }))
                })
            }))
            put("generationConfig", JSONObject().put("temperature", 0.0))
        }
        return postChatFull(
            "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$key", null,
            body,
        )?.text
    }

    /** Промпт перевода под язык назначения: кириллица для RU, латиница для EN. */
    fun trPrompt(text: String, target: String): String = if (target == "en") {
        "Translate this line of a visual novel / game into natural ENGLISH.\n" +
            "Output ONLY the translation, in Latin letters. Keep names as-is.\n" +
            "No quotes, no notes.\n\nText:\n$text"
    } else {
        "Переведи реплику комикса на естественный русский.\n" +
            "Пиши ТОЛЬКО кириллицей. Не оставляй английских слов (кроме имён).\n" +
            "Без кавычек и пояснений.\n\nТекст:\n$text"
    }

    fun translateZen(text: String, model: String, target: String = "ru"): String? {
        val words = text.split(Regex("\\s+")).size
        return chat(
            "https://opencode.ai/zen/v1/chat/completions", null, model,
            trPrompt(text, target), tokensFor(words),
        )
    }

    fun translateOpenRouter(text: String, key: String, model: String, target: String = "ru"): String? {
        if (key.isBlank()) return null
        val words = text.split(Regex("\\s+")).size
        return chat(
            "https://openrouter.ai/api/v1/chat/completions", "Bearer $key", model,
            trPrompt(text, target), tokensFor(words),
        )
    }

    fun translateGemini(ctx: android.content.Context, text: String, target: String = "ru"): String? {
        val key = EnginePrefs.googleApiKey(ctx)
        if (key.isBlank()) return null
        val model = EnginePrefs.googleModel(ctx).ifBlank { GEMINI_FREE.first() }
        val prompt = if (target == "en") {
            "Translate into natural ENGLISH (Latin letters only). " +
                "No notes or quotes. Output only the translation:\n$text"
        } else {
            "Переведи на естественный русский язык (только кириллица, без латиницы). " +
                "Никаких пояснений или кавычек. Только перевод:\n$text"
        }
        val body = JSONObject().apply {
            put("contents", JSONArray().put(JSONObject().apply {
                put("parts", JSONArray().put(JSONObject().put("text", prompt)))
            }))
            put("generationConfig", JSONObject().put("temperature", 0.0))
        }
        return postJson(
            "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$key", null,
            body,
        )
    }

    /** Ask the LLM who speaks this dialogue (MALE/FEMALE/TEEN/NARRATOR). */
    fun detectSpeaker(ctx: android.content.Context, text: String): VoiceKind? {
        val key = EnginePrefs.googleApiKey(ctx)
        if (key.isBlank()) return null
        val model = EnginePrefs.googleModel(ctx).ifBlank { GEMINI_FREE.first() }
        val prompt = "Look at this short dialogue text and return the speaker's gender as a single word: " +
            "MALE, FEMALE, TEEN, or NARRATOR. Just the word, no explanation.\n\nText:\n$text"
        val body = JSONObject().apply {
            put("contents", JSONArray().put(JSONObject().apply {
                put("parts", JSONArray().put(JSONObject().put("text", prompt)))
            }))
            put("generationConfig", JSONObject().put("temperature", 0.0))
        }
        val raw = runCatching {
            val c = URL("https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$key")
                .openConnection() as HttpURLConnection
            c.requestMethod = "POST"
            c.doOutput = true
            c.connectTimeout = 8000
            c.readTimeout = 12000
            c.setRequestProperty("Content-Type", "application/json")
            c.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
            val out = if (c.responseCode in 200..299) c.inputStream.bufferedReader().readText() else ""
            c.disconnect()
            out
        }.getOrNull() ?: return null

        return runCatching {
            val word = JSONObject(raw).optJSONArray("candidates")?.optJSONObject(0)
                ?.optJSONObject("content")?.optJSONArray("parts")?.optJSONObject(0)?.optString("text", "")
                ?.trim()?.split(" ")?.firstOrNull()?.uppercase() ?: return@runCatching null
            when (word) {
                "MALE" -> VoiceKind.MALE
                "FEMALE" -> VoiceKind.FEMALE
                "TEEN" -> VoiceKind.TEEN
                else -> VoiceKind.OTHER
            }
        }.getOrNull()
    }

    fun postJson(endpoint: String, bearer: String?, body: JSONObject): String? =
        postChatFull(endpoint, bearer, body)?.text

    /**
     * POST json → [ChatResult]. Понимает оба формата ответа:
     * OpenAI-совместимый (`choices[0].message.content` + `usage.total_tokens`)
     * и Gemini (`candidates[0].content.parts[0].text` + `usageMetadata.totalTokenCount`).
     * Возвращает null при сетевой ошибке или пустом тексте.
     */
    fun postChatFull(endpoint: String, bearer: String?, body: JSONObject): ChatResult? {
        return runCatching {
            val c = URL(endpoint).openConnection() as HttpURLConnection
            c.requestMethod = "POST"
            c.doOutput = true
            c.connectTimeout = 15_000
            c.readTimeout = 35_000
            c.setRequestProperty("Content-Type", "application/json")
            c.setRequestProperty("HTTP-Referer", "https://github.com/sj0404-collab/overlay-translator")
            c.setRequestProperty("X-Title", "OverlayTranslator")
            if (!bearer.isNullOrBlank()) c.setRequestProperty("Authorization", bearer)
            c.outputStream.use { it.write(body.toString().toByteArray()) }
            val raw = if (c.responseCode in 200..299) {
                c.inputStream.bufferedReader().readText()
            } else {
                c.errorStream?.bufferedReader()?.readText().orEmpty()
            }
            c.disconnect()
            if (raw.isBlank()) return@runCatching null
            val json = runCatching { JSONObject(raw) }.getOrNull() ?: return@runCatching null

            // OpenAI-совместимый формат.
            val choices = json.optJSONArray("choices")
            if (choices != null && choices.length() > 0) {
                val msg = choices.optJSONObject(0)
                    ?.optJSONObject("message")
                    ?.optString("content")
                    ?.trim()
                val usage = json.optJSONObject("usage")
                val tokens = usage?.optLong("total_tokens", 0L) ?: 0L
                if (!msg.isNullOrBlank()) {
                    return@runCatching ChatResult(RuText.clean(msg), tokens)
                }
            }

            // Формат Gemini.
            val cands = json.optJSONArray("candidates")
            if (cands != null && cands.length() > 0) {
                val txt = cands.optJSONObject(0)
                    ?.optJSONObject("content")
                    ?.optJSONArray("parts")
                    ?.optJSONObject(0)
                    ?.optString("text")
                    ?.trim()
                val tokens = json.optJSONObject("usageMetadata")
                    ?.optLong("totalTokenCount", 0L) ?: 0L
                if (!txt.isNullOrBlank()) {
                    return@runCatching ChatResult(RuText.clean(txt), tokens)
                }
            }
            null
        }.getOrNull()
    }

    /* ───────────────── helpers ───────────────── */

    private fun chat(endpoint: String, bearer: String?, model: String, prompt: String, maxTok: Int): String? {
        val body = JSONObject().put("model", model).put("max_tokens", maxTok)
            .put("messages", JSONArray().put(JSONObject().put("role", "user").put("content", prompt)))
        return postJson(endpoint, bearer, body)
    }

    /** Build a vision-call JSON body with intermediate variables (no paren counting). */
    private fun visionBody(model: String, bmp: Bitmap, prompt: String, maxTok: Int, maxSide: Int): JSONObject {
        val b64 = toJpegB64(bmp, maxSide)
        val userText = JSONObject().put("type", "text").put("text", prompt)
        val userImage = JSONObject().put("type", "image_url")
            .put("image_url", JSONObject().put("url", "data:image/jpeg;base64,$b64"))
        val content = JSONArray().put(userText).put(userImage)
        val userMessage = JSONObject().put("role", "user").put("content", content)
        val messages = JSONArray().put(userMessage)
        return JSONObject()
            .put("model", model)
            .put("max_tokens", maxTok)
            .put("messages", messages)
    }

    private fun ocrPrompt(russianOnly: Boolean, scanMode: String): String {
        val lang = if (russianOnly)
            "Текст ТОЛЬКО на русском (кириллица). Латиницу не пиши, кроме имён если они реально на экране."
        else "Any text visible in this image. English, Russian, Japanese, or any other language. Transcribe exactly as written."
        val modeHint = when (scanMode) {
            "bubble" -> "This is one speech bubble. Extract only the dialogue inside."
            "full" -> "Extract all readable dialogue, top to bottom."
            else -> "Extract all printed text in the selected area."
        }
        return "$modeHint $lang Output ONLY the raw text, keep line breaks and spaces between words. No comments."
    }

    private fun guessWords(bmp: Bitmap): Int {
        val area = bmp.width * bmp.height
        return (area / 14000).coerceIn(4, 40)
    }

    private fun toJpegB64(bmp: Bitmap, maxSide: Int): String {
        val m = maxOf(bmp.width, bmp.height)
        val scaled = if (m > maxSide) {
            val s = maxSide.toFloat() / m
            Bitmap.createScaledBitmap(bmp,
                (bmp.width * s).toInt().coerceAtLeast(32),
                (bmp.height * s).toInt().coerceAtLeast(32), true)
        } else bmp
        val os = ByteArrayOutputStream()
        scaled.compress(Bitmap.CompressFormat.JPEG, 62, os)
        return Base64.encodeToString(os.toByteArray(), Base64.NO_WRAP)
    }
}

/** Пол говорящего (для выбора голоса TTS) — как в overlay-translator. */
enum class VoiceKind { MALE, FEMALE, TEEN, NARRATOR, OTHER }

package app.yomikaioverlay.ot

import android.graphics.Bitmap
import android.util.Log
import java.io.ByteArrayOutputStream
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL
import kotlin.random.Random

/**
 * Google Lens OCR via protobuf endpoint.
 * Ported from Yomihon's GlensOcrEngine.
 *
 * Falls back gracefully: returns empty string on any error so that
 * [OcrRouter] can try the next engine.
 */
class GlensOcrEngine : OcrEngine {

    override fun recognizeText(image: Bitmap): String {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val maxDim = maxOf(image.width, image.height)
        val resized = if (maxDim > MAX_IMAGE_DIMENSION) {
            val s = MAX_IMAGE_DIMENSION.toFloat() / maxDim.toFloat()
            Bitmap.createScaledBitmap(image, 
                (image.width * s).toInt().coerceAtLeast(1),
                (image.height * s).toInt().coerceAtLeast(1),
                true,
            )
        } else null
        val working = resized ?: image
        return try {
            val encoded = ByteArrayOutputStream()
            if (!working.compress(Bitmap.CompressFormat.PNG, 100, encoded))
                throw IOException("PNG encode failed")
            val payload = buildRequestPayload(encoded.toByteArray(), working.width, working.height)
            val resp = executeRequest(payload)
            extractText(resp)
        } catch (e: Exception) {
            Log.w(TAG, "Glens failed, returning empty", e)
            ""
        } finally {
            resized?.recycle()
        }
    }

    /* ─────────── Request ─────────── */

    internal fun buildRequestPayload(pngBytes: ByteArray, w: Int, h: Int): ByteArray {
        // Must be non-negative for uint64 varint encoding
        val requestId = Random.nextLong().toLong() and Long.MAX_VALUE
        return ProtoWriter().apply {
            writeMessage(1) { objReq ->
                // objects_request_context
                objReq.writeMessage(1) { ctx ->
                    // request_id
                    ctx.writeMessage(3) { rid ->
                        rid.writeUInt64(1, requestId)
                        rid.writeInt32(2, 0)
                        rid.writeInt32(3, 0)
                        rid.writeBytes(4, Random.nextBytes(16))
                    }
                    // client_context
                    ctx.writeMessage(4) { cc ->
                        cc.writeInt32(1, PLATFORM_WEB)
                        cc.writeInt32(2, SURFACE_CHROMIUM)
                        cc.writeMessage(4) { lc ->
                            lc.writeString(1, DEFAULT_CLIENT_LANGUAGE)
                            lc.writeString(2, DEFAULT_CLIENT_REGION)
                        }
                        cc.writeMessage(7) { filters ->
                            filters.writeMessage(1) { fl ->
                                fl.writeInt32(1, AUTO_FILTER)
                            }
                        }
                    }
                }
                // image_data
                objReq.writeMessage(3) { img ->
                    img.writeMessage(1) { p ->
                        p.writeBytes(1, pngBytes)
                    }
                    img.writeMessage(3) { m ->
                        m.writeInt32(1, w)
                        m.writeInt32(2, h)
                    }
                }
            }
        }.toByteArray()
    }

    /* ─────────── HTTP ─────────── */

    private fun executeRequest(payload: ByteArray): ByteArray {
        val conn = (URL(LENS_ENDPOINT).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 10_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/x-protobuf")
            setRequestProperty("User-Agent", DEFAULT_USER_AGENT)
            setRequestProperty("X-Goog-Api-Key", API_KEY)
        }
        return try {
            conn.outputStream.use { it.write(payload) }
            val status = conn.responseCode
            val bytes = (if (status in 200..299) conn.inputStream else conn.errorStream)
                ?.use { it.readBytes() } ?: ByteArray(0)
            if (status !in 200..299)
                throw IOException("HTTP $status: ${bytes.toString(Charsets.UTF_8).take(200)}")
            bytes
        } finally {
            conn.disconnect()
        }
    }

    /* ─────────── Response parser ─────────── */

    private fun extractText(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val allLines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3
            val wire = tag and 0x7
            if (field == 2 && wire == 2) {
                allLines += parseObjectsResponse(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return allLines.joinToString("\n").trim()
    }

    private fun parseObjectsResponse(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 3 && wire == 2) lines += parseText(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseText(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val result = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) result += parseTextLayout(reader.readBytes())
            else reader.skipField(wire)
        }
        return result
    }

    private fun parseTextLayout(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) lines += parseParagraph(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseParagraph(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 2 && wire == 2) lines += parseLine(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    /** A "line" is a sequence of words; each word carries its own trailing separator. */
    private fun parseLine(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val sb = StringBuilder()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) {
                sb.append(parseWord(reader.readBytes()))
            } else {
                reader.skipField(wire)
            }
        }
        return sb.toString()
    }

    /** Returns text + separator (e.g. "Hello" + " "). */
    private fun parseWord(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        var text = ""
        var separator = ""
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            when {
                field == 2 && wire == 2 -> text = reader.readString()
                field == 3 && wire == 2 -> separator = reader.readString()
                else -> reader.skipField(wire)
            }
        }
        return text + separator
    }

    override fun close() {}

    companion object {
        private const val TAG = "Glens"
        private const val LENS_ENDPOINT = "https://lensfrontend-pa.googleapis.com/v1/crupload"
        private const val API_KEY = "AIzaSyDr2UxVnv_U85AbhhY8XSHSIavUW0DC-sY"
        private val DEFAULT_USER_AGENT =
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36"
        private const val DEFAULT_CLIENT_LANGUAGE = "ru"
        private const val DEFAULT_CLIENT_REGION = "Europe/Moscow"
        private const val MAX_IMAGE_DIMENSION = 1500
        private const val PLATFORM_WEB = 3
        private const val SURFACE_CHROMIUM = 4
        private const val AUTO_FILTER = 1
    }
}

/* ────────────────────────────────────────────────
 *  Minimal protobuf reader / writer — no deps
 * ──────────────────────────────────────────────── */

internal class ProtoReader(private val bytes: ByteArray) {
    private var pos = 0

    fun hasRemaining() = pos < bytes.size

    fun readTag(): Int? = if (hasRemaining()) readVarint32() else null

    fun readBytes(): ByteArray {
        val len = readVarint32() ?: return ByteArray(0)
        val safeLen = len.coerceAtMost(bytes.size - pos)
        val result = bytes.copyOfRange(pos, pos + safeLen)
        pos += safeLen
        return result
    }

    fun readString(): String = readBytes().toString(Charsets.UTF_8)

    fun skipField(wireType: Int) {
        when (wireType) {
            0 -> readVarint32()
            1 -> { pos += 8; if (pos > bytes.size) pos = bytes.size }
            2 -> { val len = readVarint32() ?: 0; pos += len.coerceAtMost(bytes.size - pos); if (pos > bytes.size) pos = bytes.size }
            5 -> { pos += 4; if (pos > bytes.size) pos = bytes.size }
        }
    }

    internal fun readVarint32(): Int? {
        var result = 0L
        var shift = 0
        while (shift < 64) {
            if (!hasRemaining()) return null
            val b = bytes[pos++].toLong() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80L) == 0L) return result.toInt()
            shift += 7
        }
        return result.toInt()
    }

    /** Полный 64-битный varint: длинные значения (uint64) больше не рвут поток. */
    internal fun readVarint64(): Long? {
        var result = 0L
        var shift = 0
        while (shift < 64) {
            if (!hasRemaining()) return null
            val b = bytes[pos++].toLong() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80L) == 0L) return result
            shift += 7
        }
        return result
    }
}

internal class ProtoWriter {
    private val out = ByteArrayOutputStream()

    fun writeInt32(fieldNumber: Int, value: Int) {
        writeTag(fieldNumber, 0); writeVarint32(value)
    }

    fun writeUInt64(fieldNumber: Int, value: Long) {
        writeTag(fieldNumber, 0); writeVarint64(value)
    }

    fun writeString(fieldNumber: Int, value: String) {
        writeBytes(fieldNumber, value.toByteArray(Charsets.UTF_8))
    }

    fun writeBytes(fieldNumber: Int, value: ByteArray) {
        writeTag(fieldNumber, 2); writeVarint32(value.size); out.write(value)
    }

    fun writeMessage(fieldNumber: Int, block: (ProtoWriter) -> Unit) {
        val inner = ProtoWriter().also(block).toByteArray()
        writeBytes(fieldNumber, inner)
    }

    fun toByteArray(): ByteArray = out.toByteArray()

    private fun writeTag(field: Int, wire: Int) = writeVarint32((field shl 3) or wire)

    private fun writeVarint32(value: Int) {
        var v = value
        while ((v and 0x7F.inv()) != 0) { out.write((v and 0x7F) or 0x80); v = v ushr 7 }
        out.write(v and 0x7F)
    }

    private fun writeVarint64(value: Long) {
        var v = value
        // маска ~0x7F (а не ~0x80): иначе в поток уходил лишний нулевой байт
        // и varint переставал быть каноническим.
        while ((v and 0x7FL.inv()) != 0L) { out.write(((v and 0x7F) or 0x80).toInt()); v = v ushr 7 }
        out.write((v and 0x7F).toInt())
    }
}

package app.yomikaioverlay.ot

import android.content.Context
import android.graphics.Bitmap
import org.json.JSONArray
import org.json.JSONObject
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL
import java.util.Base64

/**
 * Vision OCR routed through OpenRouter. Uses a user-supplied API key from
 * [EnginePrefs.openrouterKey] and a model picked in [EnginePrefs.orModel].
 * Defaults align with Yomihon's reader build (`google/gemini-2.5-flash`).
 */
class OpenRouterOcrEngine(private val ctx: Context) : OcrEngine {

    override fun recognizeText(image: Bitmap): String {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val key = EnginePrefs.openrouterKey(ctx)
        if (key.isBlank()) throw IllegalStateException("OpenRouter API key is empty")
        val model = EnginePrefs.orModel(ctx).ifBlank { "google/gemini-2.5-flash" }
        val base64 = encodePngBase64(image)

        val json = JSONObject().apply {
            put("model", model)
            put("temperature", 0.0)
            val msgs = JSONArray()
            val userMsg = JSONObject()
            userMsg.put("role", "user")
            val content = JSONArray()
            content.put(JSONObject().apply {
                put("type", "text")
                put("text", "Perform STRICT OPTICAL CHARACTER RECOGNITION (OCR) ONLY. " +
                    "Transcribe the exact text from the image verbatim without translating, " +
                    "explaining, summarizing, or adding any commentary. If no text is visible, " +
                    "return empty string.")
            })
            content.put(JSONObject().apply {
                put("type", "image_url")
                put("image_url", JSONObject().apply {
                    put("url", "data:image/png;base64,$base64")
                })
            })
            userMsg.put("content", content)
            msgs.put(userMsg)
            put("messages", msgs)
        }

        val connection = (URL(ENDPOINT).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 15_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/json")
            setRequestProperty("Authorization", "Bearer $key")
            setRequestProperty("HTTP-Referer", "https://github.com/sj0404-collab/overlay-translator")
            setRequestProperty("X-Title", "OverlayTranslator")
        }
        return try {
            connection.outputStream.use { it.write(json.toString().toByteArray(Charsets.UTF_8)) }
            val status = connection.responseCode
            val body = (if (status in 200..299) connection.inputStream else connection.errorStream)
                ?.use { it.readBytes().toString(Charsets.UTF_8) } ?: ""
            if (status !in 200..299) throw RuntimeException("OpenRouter failed HTTP $status: ${body.take(200)}")
            val resp = JSONObject(body)
            val choices = resp.optJSONArray("choices")
            val extracted = if (choices != null && choices.length() > 0) {
                choices.getJSONObject(0).optJSONObject("message")?.optString("content", "") ?: ""
            } else ""
            val tokens = resp.optJSONObject("usage")?.optLong("total_tokens", 100L) ?: 100L
            EnginePrefs.incrementTokens(ctx, tokens)
            extracted.trim()
        } finally {
            connection.disconnect()
        }
    }

    private fun encodePngBase64(bitmap: Bitmap): String {
        val baos = ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.PNG, 90, baos)
        return Base64.getEncoder().encodeToString(baos.toByteArray())
    }

    companion object {
        private const val ENDPOINT = "https://openrouter.ai/api/v1/chat/completions"
    }
}

