package app.yomikaioverlay.ot

import android.content.Context
import android.graphics.Bitmap

/**
 * «Zen Free» — бесплатный ИИ-хаб: перебирает модели [LlmClient.ZEN_FREE]
 * и берёт первую, ответившую текстом. Ключ не нужен.
 *
 * Если хаб недоступен (403/сеть/пустой ответ) — молча падаем на Google Lens,
 * который тоже бесключевой: пользователь всегда получает результат скана,
 * а не пустой экран.
 */
class ZenFreeOcrEngine(private val ctx: Context) : OcrEngine {

    private val fallbackGlens by lazy { GlensOcrEngine() }

    override fun recognizeText(image: Bitmap): String {
        for (model in LlmClient.ZEN_FREE) {
            try {
                val result = LlmClient.visionFull(
                    image, model, russianOnly = false, scanMode = "rect",
                )
                if (result != null && result.text.isNotBlank()) {
                    if (result.totalTokens > 0) {
                        EnginePrefs.incrementTokens(ctx, result.totalTokens)
                    }
                    return result.text
                }
            } catch (e: Exception) {
                // следующая модель
            }
        }
        val lens = try { fallbackGlens.recognizeText(image) } catch (e: Exception) { "" }
        if (lens.isNotBlank()) {
            EnginePrefs.incrementTokens(ctx, (lens.length * 1.5f).toLong().coerceAtLeast(15L))
        }
        return lens
    }

    override fun close() {
        fallbackGlens.close()
    }
}

package app.yomikaioverlay.ot

import org.json.JSONArray
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder

/**
 * Free, no-key Google Translate gateway lifted straight from Yomihon's
 * reader build ([MangaTranslatorService]). Used by the overlay as the
 * cheapest possible translation route for short snippets.
 */
object MangaTranslatorService {

    fun translate(
        text: String,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): String {
        if (text.isBlank()) return ""
        return translateOrNull(text, targetLang, sourceLang) ?: text
    }

    /**
     * То же, но null при ошибке сети/непарсиваго ответе — чтобы вызывающий
     * мог перейти к следующему маршруту перевода. Старый [translate] никогда
     * не возвращал null, из-за чего каскад фолбэков дальше него не шёл.
     */
    fun translateOrNull(
        text: String,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): String? {
        if (text.isBlank()) return null
        return runCatching {
            val encoded = URLEncoder.encode(text, "UTF-8")
            val url = "https://translate.googleapis.com/translate_a/single?client=gtx" +
                "&sl=$sourceLang&tl=$targetLang&dt=t&q=$encoded"
            val connection = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "GET"
                connectTimeout = 8_000
                readTimeout = 15_000
                setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
            }
            val code = connection.responseCode
            val body = if (code in 200..299) {
                connection.inputStream.use { it.readBytes().toString(Charsets.UTF_8) }
            } else ""
            connection.disconnect()
            if (body.isBlank()) return null
            val arr = JSONArray(body)
            val sentences = arr.optJSONArray(0) ?: return null
            val sb = StringBuilder()
            for (i in 0 until sentences.length()) {
                val sentence = sentences.optJSONArray(i) ?: continue
                sb.append(sentence.optString(0, ""))
            }
            sb.toString().trim().ifBlank { null }
        }.getOrNull()
    }
}

