package app.yomikaioverlay.ot

import android.content.Context
import android.content.Intent
import android.graphics.drawable.Drawable

/**
 * Список запускаемых приложений устройства — чтобы открыть нужное в один тап,
 * а не искать его в списке приложений телефона.
 */
object AppCatalog {

    class App(
        val pkg: String,
        val label: String,
    )

    private var cache: List<App>? = null

    /** Все приложения с лаунчером, отсортированные по названию. */
    fun load(ctx: Context, force: Boolean = false): List<App> {
        cache?.let { if (!force) return it }
        val pm = ctx.packageManager
        val out = ArrayList<App>()
        try {
            val pkgs = pm.getInstalledPackages(0)
            for (p in pkgs) {
                if (pm.getLaunchIntentForPackage(p.packageName) == null) continue
                val label = try {
                    pm.getApplicationLabel(p.applicationInfo).toString()
                } catch (e: Exception) { continue }
                out.add(App(p.packageName, label))
            }
        } catch (e: Exception) { }
        val sorted = out.sortedBy { it.label.lowercase() }
        cache = sorted
        return sorted
    }

    /** Иконка приложения (рисуется в списке). */
    fun icon(ctx: Context, app: App): Drawable? = try {
        ctx.packageManager.getApplicationIcon(app.pkg)
    } catch (e: Exception) {
        null
    }

    /**
     * Поиск по названию или пакету. Пустой запрос — отдаём всё.
     * Регистр не учитываем, пробелы в запросе склеиваем.
     */
    fun filter(apps: List<App>, query: String?): List<App> {
        val q = query?.trim()?.lowercase()?.replace(" ", "") ?: return apps
        if (q.isEmpty()) return apps
        return apps.filter {
            it.label.lowercase().replace(" ", "").contains(q) ||
                it.pkg.lowercase().contains(q)
        }
    }

    /** Запустить приложение. */
    fun launch(ctx: Context, app: App): Boolean {
        return try {
            val i = ctx.packageManager.getLaunchIntentForPackage(app.pkg) ?: return false
            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            ctx.startActivity(i)
            true
        } catch (e: Exception) {
            false
        }
    }
}

package app.yomikaioverlay.ot

import android.graphics.Bitmap
import android.graphics.Rect
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.text.TextRecognition
import com.google.mlkit.vision.text.TextRecognizer
import com.google.mlkit.vision.text.latin.TextRecognizerOptions
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit

data class LayoutBlock(val text: String, val rect: Rect)

/**
 * Гибридная пометка: ML Kit даёт координаты блоков текста (рамки + номера +
 * порядок чтения), а сам распознанный текст для озвучки/перевода остаётся
 * онлайн (Lens/Zen) — поэтому покоординатная часть может жить на устройстве.
 *
 * Если Play Services / ML-модель недоступны — [isAvailable] == false и оверлей
 * работает как раньше, без рамок и номеров.
 */
class LayoutOcr {
    private var recognizer: TextRecognizer? = createClient()

    val isAvailable: Boolean get() = recognizer != null

    /** Синхронно (worker-поток): блоки с координатами в пикселях битмапа. */
    fun blocks(bitmap: Bitmap): List<LayoutBlock> {
        val rec = recognizer ?: return emptyList()
        val latch = CountDownLatch(1)
        var result: com.google.mlkit.vision.text.Text? = null
        var failed = false
        try {
            val task = rec.process(InputImage.fromBitmap(bitmap, 0))
            task.addOnSuccessListener { r -> result = r; latch.countDown() }
            task.addOnFailureListener { _ -> failed = true; latch.countDown() }
        } catch (e: Throwable) {
            failed = true
            latch.countDown()
        }
        try { latch.await(15, TimeUnit.SECONDS) } catch (e: InterruptedException) { }
        if (failed || result == null) {
            recognizer = null
            return emptyList()
        }
        // Строчный уровень: рамки точнее и складываются в колонки текста,
        // тогда как блочный уровень даёт крупные «разбросанные» прямоугольники.
        return result.textBlocks
            .flatMap { it.lines }
            .mapNotNull { ln ->
                val box = ln.boundingBox ?: return@mapNotNull null
                if (ln.text.isBlank()) return@mapNotNull null
                LayoutBlock(ln.text, box)
            }
    }

    fun close() {
        try { recognizer?.close() } catch (e: Throwable) { }
        recognizer = null
    }

    private companion object {
        fun createClient(): TextRecognizer? = try {
            TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)
        } catch (e: Throwable) {
            null
        }
    }
}

