class EnginesTest {

    @Test
    fun `next cycles all four engines`() {
        assertEquals(Engines.ZEN, Engines.next(Engines.LENS))
        assertEquals(Engines.GOOGLE_AI, Engines.next(Engines.ZEN))
        assertEquals(Engines.OPENROUTER, Engines.next(Engines.GOOGLE_AI))
        assertEquals(Engines.LENS, Engines.next(Engines.OPENROUTER))
    }

